-- CAT_QUELTHALAS
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].name = "Lor'themar Theron"
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].aliases = {"Lor'themar"}
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].lore =
[[
A ranger at heart, Lor'themar Theron didn't choose to lead the blood elves. When Quel'thalas fell to the Scourge in the Third War he was appointed, in absence of any other surviving candidates, to serve the fallen kingdom as regent by Prince Kael'thas.

He was forced to make difficult decisions, such as allying the blood elves with the Horde, exiling the high elves to combat unrest, and leading the battle against Kael'thas after the prince's betrayal. Lor'themar's pragmatism and strategic cunning made him an inspiring leader nontheless, commanding respect from friends and foes alike. 

A staunch advocate for peace, Lor'themar serves now both as regent lord of Quel'thalas and as a member of the Horde's ruling council. His loyality lies first and foremost with his people.

Now, with Quel'thalas in peril once again, he will stop at nothing to defend his people and his city against the encroaching forces of the void.]]
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].zones = {"Amirdrassil", "Harandar", "Eversong Woods", "Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].source = "warcraft.wiki.gg/wiki/Lor'themar_Theron"
IMAGOdb.npcs.CAT_QUELTHALAS["lorthemar_theron_midnight"].timeline = IMAGOdb.timelines.LORTHEMAR_THERON

IMAGOdb.npcs.CAT_QUELTHALAS["erste_arkanistin_thalyssra_midnight"].name = "First Arcanist Thalyssra"
IMAGOdb.npcs.CAT_QUELTHALAS["erste_arkanistin_thalyssra_midnight"].aliases = {"Thalyssra", "Arcanist Thalyssra", "Dusk Lily"}
IMAGOdb.npcs.CAT_QUELTHALAS["erste_arkanistin_thalyssra_midnight"].race = "Nightborne"
IMAGOdb.npcs.CAT_QUELTHALAS["erste_arkanistin_thalyssra_midnight"].lore = "First Arcanist Thalyssra is the leader of the nightborne elves. Once exiled from her home city of Suramar by a corrupt ruler, First Arcanist Thalyssra has liberated the shal'dorei people of their addiction to their Nightwell's power, stepping up to lead after the sacking of Suramar. She now rules her people arm in arm with Lor'themar Theron's blood elves, uniting the two cultures through unity in the Horde, and the unity of their marriage"
IMAGOdb.npcs.CAT_QUELTHALAS["erste_arkanistin_thalyssra_midnight"].zones = {"Amirdrassil", "The Eternal Palace", "Isle of Quel'Danas", "Silvermoon City", "Suramar"}
IMAGOdb.npcs.CAT_QUELTHALAS["erste_arkanistin_thalyssra_midnight"].source = ""
IMAGOdb.npcs.CAT_QUELTHALAS["erste_arkanistin_thalyssra_midnight"].timeline = IMAGOdb.timelines.ERSTE_ARKANISTIN_THALYSSRA

IMAGOdb.npcs.CAT_QUELTHALAS["lady_liadrin_midnight"].name = "Lady Liadrin"
IMAGOdb.npcs.CAT_QUELTHALAS["lady_liadrin_midnight"].aliases = {"Liadrin"}
IMAGOdb.npcs.CAT_QUELTHALAS["lady_liadrin_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["lady_liadrin_midnight"].lore = [[Lady Liadrin lost her faith in the Light when the Scourge decimated Silvermoon. She wandered the Ghostlands, killing undead in the ruins of her former home. Eventually, the Magisters came to her with an offer to use the Naaru M'uru's energies to wield the Light once more as a paladin. In doing so, Liadrin became the first Blood Knight.

After the renewal of the Sunwell, her conviction was restored as well and she swore to protect it henceforth.

Sometimes she may still doubt her worthiness for what she did to M'uru, but her faith and devotion to her people never wavered.]]
IMAGOdb.npcs.CAT_QUELTHALAS["lady_liadrin_midnight"].zones = {"Atal'Aman", "Dornogal", "Eversong Woods", "Isle of Quel'Danas", "Orgrimmar", "Parhelion Plaza", "Silvermoon City", "Stormwind City", "Zul'Aman"}
IMAGOdb.npcs.CAT_QUELTHALAS["lady_liadrin_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["lady_liadrin_midnight"].timeline = IMAGOdb.timelines.LADY_LIADRIN

IMAGOdb.npcs.CAT_QUELTHALAS["grand_magister_rommath_midnight"].name = "Grand Magister Rommath"
IMAGOdb.npcs.CAT_QUELTHALAS["grand_magister_rommath_midnight"].aliases = {"Magister Rommath", "Rommath"}
IMAGOdb.npcs.CAT_QUELTHALAS["grand_magister_rommath_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["grand_magister_rommath_midnight"].lore = [[Uncompromising and confrontational, the Grand Magister of Silvermoon is a man fiercely loyal to his people. As Kael'thas' staunchest supporter after the Third War, Rommath did whatever he thought was necessary to ensure the survival of the blood elves. Even if it meant using fel magic or torturing a Naaru for its holy power, Rommath was ready and willing. 

His loyalty was tested when Kael'thas allied himself with the Burning Legion; in the end, he chose his people over his former prince. Having been betrayed twice already – first by his former friend Dar'khan Drathir, and second by the Kirin Tor of Dalaran – Kael'thas' treachery hardened the elf's heart even further.

With the Voidstorm encroaching on his homeland, Rommath will do what he has always done – protect Silvermoon at all costs, despite everything he and his people have endured.]]
IMAGOdb.npcs.CAT_QUELTHALAS["grand_magister_rommath_midnight"].zones = {"Eversong Woods", "Orgrimmar", "Twilight Highlands", "Silvermoon City"}
IMAGOdb.npcs.CAT_QUELTHALAS["grand_magister_rommath_midnight"].source = "Cadash & Austin"
IMAGOdb.npcs.CAT_QUELTHALAS["grand_magister_rommath_midnight"].timeline = IMAGOdb.timelines.GRAND_MAGISTER_ROMMATH

IMAGOdb.npcs.CAT_QUELTHALAS["halduron_brightwing_midnight"].name = "Halduron Brightwing"
IMAGOdb.npcs.CAT_QUELTHALAS["halduron_brightwing_midnight"].aliases = {"Halduron"}

IMAGOdb.npcs.CAT_QUELTHALAS["halduron_brightwing_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["halduron_brightwing_midnight"].lore =
[[
The current Ranger-General of Silvermoon and best friend of Lor'themar Theron, Halduron Brightwing keeps the borders of his homeland safe. He has served his people for decades, standing against every threat thrown at him with unwavering courage – from Amani troll invaders to the horrifying undead of the Scourge.
    
Despite the deadly fervor he shows his enemies on the field of battle, Halduron is known to his friends as a tolerant and bright-spirited man with a good eye for detail.]]
IMAGOdb.npcs.CAT_QUELTHALAS["halduron_brightwing_midnight"].zones = {"The Den", "Harandar", "Eversong Woods", "Silvermoon City"}
IMAGOdb.npcs.CAT_QUELTHALAS["halduron_brightwing_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["halduron_brightwing_midnight"].timeline = IMAGOdb.timelines.HALDURON_BRIGHTWING

IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].name = "Vereesa Windrunner"
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].aliases = {"Vereesa"}
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].race = "High Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].lore = [[Vereesa is the youngest of the Windrunner sisters. Her life changed when the Horde arrived on Azeroth and she was unable to prevent the death of her younger brother, Lirath. She raised Arator, her sister Alleria's son, and aided the mage Rhonin in his mission to rescue the dragon Alexstrasza. However, her life was marked by tragedy when she found herself completely alone after the death of everything she knew at the hands of Arthas and the death of her husband Rhonin following the destruction of Theramore. This led her to commit acts that would forever affect her reputation with the blood elves.]]
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].zones = {"Eversong Woods", "Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].source = "Karstan"
IMAGOdb.npcs.CAT_QUELTHALAS["vereesa_windrunner_midnight"].timeline = IMAGOdb.timelines.VEREESA_WINDRUNNER

IMAGOdb.npcs.CAT_QUELTHALAS["shandris_feathermoon_midnight"].name = "Shandris Feathermoon"
IMAGOdb.npcs.CAT_QUELTHALAS["shandris_feathermoon_midnight"].aliases = {"Shandris"}
IMAGOdb.npcs.CAT_QUELTHALAS["shandris_feathermoon_midnight"].race = "Night Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["shandris_feathermoon_midnight"].lore = [[Orphaned during the War of the Ancients, Shandris has known battle for almost as long as she has lived. Adopted by Tyrande Whisperwind and Malfurion Stormrage, she trained as a huntress and has since become one of the most formidable archers on Azeroth.

Shandris has led the night elven and Alliance forces as high general of the Sentinel army on more than one occasion, and after being on the front lines of defense of the new world tree Amirdrassil, she now leads the Night Elves as their ruler.

Highly protective of the people she holds dear – even venturing into the realms of death itself to rescue her mother – Shandris nowadays wants peace most of all. ]]
IMAGOdb.npcs.CAT_QUELTHALAS["shandris_feathermoon_midnight"].zones = {"Amirdrassil", "Harandar", "Silvermoon City", "Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_QUELTHALAS["shandris_feathermoon_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["shandris_feathermoon_midnight"].timeline = IMAGOdb.timelines.SHANDRIS_FEATHERMOON

IMAGOdb.npcs.CAT_QUELTHALAS["aethas_sunreaver_midnight"].name = "Archmage Aethas Sunreaver"
IMAGOdb.npcs.CAT_QUELTHALAS["aethas_sunreaver_midnight"].aliases = {"Aethas", "Aethas Sunreaver"}
IMAGOdb.npcs.CAT_QUELTHALAS["aethas_sunreaver_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["aethas_sunreaver_midnight"].lore = "Archmage Aethas Sunreaver is a brilliant sin'dorei mage who rapidly ascended to the Kirin Tor's Council of Six despite his youth. An eternal optimist and a staunch proponent of neutrality, he dedicated much of his life to repairing the millennia old alliance between Silvermoon and Dalaran. His loyalties and ideals have been severely tested by factional warfare, leading to difficult choices, betrayal, and even imprisonment as he struggled to protect his people. Despite enduring immense hardships and the recurring destruction of his beloved city, Aethas remains deeply committed to the pursuit of knowledge, cooperation, and the enduring survival of the blood elves."
IMAGOdb.npcs.CAT_QUELTHALAS["aethas_sunreaver_midnight"].zones = {"Eversong Woods", "Silvermoon City"}
IMAGOdb.npcs.CAT_QUELTHALAS["aethas_sunreaver_midnight"].source = "Lewi"
IMAGOdb.npcs.CAT_QUELTHALAS["aethas_sunreaver_midnight"].timeline = IMAGOdb.timelines.AETHAS_SUNREAVER

IMAGOdb.npcs.CAT_QUELTHALAS["salandria_midnight"].name = "Salandria"
IMAGOdb.npcs.CAT_QUELTHALAS["salandria_midnight"].aliases = {}
IMAGOdb.npcs.CAT_QUELTHALAS["salandria_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["salandria_midnight"].lore = [[Salandria was orphaned when she was merely a small infant. Spending the majority of her childhood in the orphanage of Shattrath City on Outland, she was eventually adopted by Lady Liadrin, who was an adoptee herself. Now, Salandria has become a Blood Knight, fighting for Silvermoon and the Holy Light with determination and unrelenting optimism.

One thing looms over Salandria, promising a dark future: as a child, she was attacked on sight by a member of the Bronze Dragonflight for something vile she would do in her future. It is still a mystery what this ominous prophecy means for her and for the future of Azeroth.]]
IMAGOdb.npcs.CAT_QUELTHALAS["salandria_midnight"].zones = {"Eversong Woods", "Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_QUELTHALAS["salandria_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["salandria_midnight"].timeline = IMAGOdb.timelines.SALANDRIA

IMAGOdb.npcs.CAT_QUELTHALAS["magister_umbric_midnight"].name = "Magister Umbric"
IMAGOdb.npcs.CAT_QUELTHALAS["magister_umbric_midnight"].aliases = {"Umbric"}
IMAGOdb.npcs.CAT_QUELTHALAS["magister_umbric_midnight"].race = "Void Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["magister_umbric_midnight"].lore = [[No limits – that was Umbric's desire as a student of the arcane arts in Dalaran. Yet he found the mages' studies to be too rigid, too constricting for his liking. Seeing the fall of the Sunwell and his home of Quel'Thalas, he realized that he needed to try a different approach to magic. The elves of Silvermoon needed an alternative way to survive if the need arose... and so Umbric turned to the dark energies of the Void.

He gathered quite a few acolytes practicing the forbidden arts in secret before he was discovered. Exiled by his former friend, Grand Magister Rommath, Umbric and his followers continued their studies and finally found a way into a rift of space and time – Telogrus. Here, they were transformed into the ren'dorei, elves infused with the Void itself.

After joining the Alliance, Umbric and his ren'dorei have become a small but elite force of specialists and have been on the forefront in the efforts against Xal'atath multiple times by now.]]
IMAGOdb.npcs.CAT_QUELTHALAS["magister_umbric_midnight"].zones = {"Amirdrassil", "The Voidspire", "Eversong Woods", "Isle of Quel'Danas", "Voidstorm", "Twilight Highlands", "Silvermoon City", "Stormwind City", "Magister's Terrace"}
IMAGOdb.npcs.CAT_QUELTHALAS["magister_umbric_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["magister_umbric_midnight"].timeline = IMAGOdb.timelines.MAGISTER_UMBRIC

-- LADY DARKGLEN --
IMAGOdb.npcs.CAT_QUELTHALAS["lady_darkglen_midnight"].name = "Lady Darkglen"
IMAGOdb.npcs.CAT_QUELTHALAS["lady_darkglen_midnight"].aliases = {"Darkglen"}
IMAGOdb.npcs.CAT_QUELTHALAS["lady_darkglen_midnight"].race = "Void Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["lady_darkglen_midnight"].lore = [[Lady Darkglen is a noblewoman from Quel'Thalas and one of the ren'dorei's most expert alchemists and ritualists. Her free and sometimes reckless use of void magic can unsettle even some of her fellow comrades but she doesn't mind. She risked her sanity already as a warlock and then once more when becoming infused with the Void. So why shouldn't she go all out?

It comes as no surprise that she and her pet voidwalker Blocciniux join Magister Umbric in his attempt to breach the Voidstorm. What could be more fascinating than a place of pure chaos?]]
IMAGOdb.npcs.CAT_QUELTHALAS["lady_darkglen_midnight"].zones = {"Silvermoon City", "Voidstorm", "Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_QUELTHALAS["lady_darkglen_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["lady_darkglen_midnight"].timeline = IMAGOdb.timelines.LADY_DARKGLEN

-- RIFTBLADE MAELLA --
IMAGOdb.npcs.CAT_QUELTHALAS["riftblade_maella_midnight"].name = "Riftblade Maella"
IMAGOdb.npcs.CAT_QUELTHALAS["riftblade_maella_midnight"].aliases = {"Maella"}
IMAGOdb.npcs.CAT_QUELTHALAS["riftblade_maella_midnight"].race = "Void elf"
IMAGOdb.npcs.CAT_QUELTHALAS["riftblade_maella_midnight"].lore = [[Maella used to be a spellbreaker - a warrior trained to combat mages - when she was still living in Silvermoon.  She learned from Magister Umbric about the Void in secret, believing that in the forbidden magic lay the answer to help the struggling blood elves. She was caught however, and instead of renouncing her, Umbric chose to take the blame and the magister and his followers were exiled from their home.

Now deeply loyal to him, Maella followed Umbric into Telogrus Rift where she became involuntarily infused with the Void. With no way out but through, she became a Riftblade and now serves the ren'dorei's cause wherever it may lead.]]
IMAGOdb.npcs.CAT_QUELTHALAS["riftblade_maella_midnight"].zones = {"Isle of Quel'Danas", "Silvermoon City", "Sunkiller Sanctum", "The Voidspire", "Voidstorm"}
IMAGOdb.npcs.CAT_QUELTHALAS["riftblade_maella_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["riftblade_maella_midnight"].timeline = IMAGOdb.timelines.RIFTBLADE_MAELLA

IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].name = "Astalor Bloodsworn"
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].aliases = {}
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].lore =
[[
Co-founder of the Blood Knights of Silvermoon, the mage Astalor Bloodsworn has always searched for creative ways to aid his people. When Kael'thas sent the captured Naaru M'uru back to Silvermoon, it was Astalor who advised to not merely feast upon the holy creature, but instead to siphon and wield its energy to empower the blood elves into paladins. 
    
With the threat of the Voidstorm looming over Silvermoon, Astalor once again thinks of unusual methods to combat the threat: by hunting down dangerous individuals and harvesting their anguish to transform it into powerful energy. It's yet to be seen what results he will yield...]]
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].zones = {"Eversong Woods", "Harandar", "Voidstorm", "Atal'Aman", "Silvermoon City"}
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["astalor_bloodsworn_midnight"].timeline = IMAGOdb.timelines.ASTALOR_BLOODSWORN

IMAGOdb.npcs.CAT_QUELTHALAS["lord_saltheril_midnight"].name = "Lord Saltheril"
IMAGOdb.npcs.CAT_QUELTHALAS["lord_saltheril_midnight"].aliases = {"Saltheril"}
IMAGOdb.npcs.CAT_QUELTHALAS["lord_saltheril_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["lord_saltheril_midnight"].lore = [[A minor quel'dorei noble, Lord Saltheril is famous throughout Quel'Thalas for his lavish parties, where magical wines and extravagant food are provided to his guests. Saltheril was a patron of Lirath Windrunner, arranging musical performances for various Silvermoon nobles and royalty, including Prince Kael'thas Sunstrider and Lor'themar Theron.

A survivor of many calamities, including the Second War and the Scourge Invasion, Saltheril has never ceased hosting parties. Regent Lord Lor'themar remarked that not even Arthas Menethil could halt him for long.]]
IMAGOdb.npcs.CAT_QUELTHALAS["lord_saltheril_midnight"].zones = {"Eversong Woods"}
IMAGOdb.npcs.CAT_QUELTHALAS["lord_saltheril_midnight"].source = "Travanoid"
IMAGOdb.npcs.CAT_QUELTHALAS["lord_saltheril_midnight"].timeline = IMAGOdb.timelines.LORD_SALTHERIL

IMAGOdb.npcs.CAT_QUELTHALAS["lord_antenorian_midnight"].name = "Lord Antenorian"
IMAGOdb.npcs.CAT_QUELTHALAS["lord_antenorian_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_QUELTHALAS["lord_antenorian_midnight"].lore = [[Originally a magister from Silvermoon, Antenorian has always preferred the quiet of the fittingly-named Tranquilien. When he learned of Magister Umbric's research into the threat of the Voidstorm, he invited the ren'dorei into town.

As Tranquilien's governor, he is deeply protective of his citizens. With the Void darkening their skies, waiting to devour them all, Antenorian is prepared to pay any price to keep them safe.]]
IMAGOdb.npcs.CAT_QUELTHALAS["lord_antenorian_midnight"].zones = {"Eversong Wood", "The Shadow Enclave"}
IMAGOdb.npcs.CAT_QUELTHALAS["lord_antenorian_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["lord_antenorian_midnight"].timeline = IMAGOdb.timelines.LORD_ANTENORIAN

-- LEONA DARKSTRIDER --
IMAGOdb.npcs.CAT_QUELTHALAS["leona_darkstrider_midnight"].name = "Leona Darkstrider"
IMAGOdb.npcs.CAT_QUELTHALAS["leona_darkstrider_midnight"].race = "Void elf"
IMAGOdb.npcs.CAT_QUELTHALAS["leona_darkstrider_midnight"].lore = [[To be ren'dorei means to live in constant danger from the whispers of the Void - a high price for great power. For young Leona, this wasn't enough. Fiercely loyal to and protective of her people, she sought out the Illidari to combine her dark talents with the ways of the demon hunters.

After a bit of a setback on K'aresh, she has now found a willing teacher in Allari the Souleater. Like her, Leona is prepared to sacrifice everything to become the perfect weapon against her enemies.]]
IMAGOdb.npcs.CAT_QUELTHALAS["leona_darkstrider_midnight"].zones = {"Silvermoon City", "Voidstorm", "Naigtal", "Eredath"}
IMAGOdb.npcs.CAT_QUELTHALAS["leona_darkstrider_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["leona_darkstrider_midnight"].timeline = IMAGOdb.timelines.LEONA_DARKSTRIDER

-- CHIEF TELEMANCER OCULETH --
IMAGOdb.npcs.CAT_QUELTHALAS["chief_telemancer_oculeth_midnight"].name = "Chief Telemancer Oculeth"
IMAGOdb.npcs.CAT_QUELTHALAS["chief_telemancer_oculeth_midnight"].race = "Nightborne"
IMAGOdb.npcs.CAT_QUELTHALAS["chief_telemancer_oculeth_midnight"].lore = [[Every Horde citizen has probably used one of Oculeth's portals before. The Suramarian mage is an expert telemancer and established the teleportation nexuses of capital cities like Orgrimmar and Dazar'alor. His skills proved of great use to his people during Thalyssra's rebellion against Grand Magistrix Elisande and to the Horde in the Fourth War.

He may come off as cranky or absent-minded at times, but one would be a fool to dismiss his eccentricities  as imprudence. Even being more of a scholar than a fighter, Oculeth has won battles against mages more adept in combat, simply by thinking outside the box and finding creative ways to bend spells in his favor.]]
IMAGOdb.npcs.CAT_QUELTHALAS["chief_telemancer_oculeth_midnight"].zones = {"Silvermoon City", "Suramar", "Amirdrassil", "Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_QUELTHALAS["chief_telemancer_oculeth_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["chief_telemancer_oculeth_midnight"].timeline = IMAGOdb.timelines.CHIEF_TELEMANCER_OCULETH

-- ARCANIST VALTROIS --
IMAGOdb.npcs.CAT_QUELTHALAS["arcanist_valtrois_midnight"].name = "Arcanist Valtrois"
IMAGOdb.npcs.CAT_QUELTHALAS["arcanist_valtrois_midnight"].race = "Nightborne"
IMAGOdb.npcs.CAT_QUELTHALAS["arcanist_valtrois_midnight"].lore = [[An expert on the study of ley lines and a powerful mage with a strategic mind, Arcanist Valtrois was one of Thalyssra's main supporters during her rebellion against Grand Magistrix Elisande. Now, she serves as one of the leaders of the nightborne. 

Valtrois may come off as brusque and even outright rude, especially to those she has just met, but once her trust is earned, she has proven to be an invaluable ally time and time again. With the war against the Burning Legion won, she now spends her time exploring and studying the world beyond her home of Suramar alongside her lover, the blue dragon Stellagosa.]]
IMAGOdb.npcs.CAT_QUELTHALAS["arcanist_valtrois_midnight"].zones = {"Isle of Quel'Danas", "The Den"}
IMAGOdb.npcs.CAT_QUELTHALAS["arcanist_valtrois_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_QUELTHALAS["arcanist_valtrois_midnight"].timeline = IMAGOdb.timelines.ARCANIST_VALTROIS

-- CAT_LIGHT

IMAGOdb.npcs.CAT_LIGHT["the_great_kyron_midnight"].name = "The Great Kyron"
IMAGOdb.npcs.CAT_LIGHT["the_great_kyron_midnight"].race = "Arathi"
IMAGOdb.npcs.CAT_LIGHT["the_great_kyron_midnight"].lore = [[The Great Kyron is the leader of the Arathi Lamplighters of Hallowfall. Before the Arathi expedition to Hallowfall, Kyron served as an overseer in the Arathi army. When they aren't fending off the increasingly frequent attacks by the nerubians of the Kaheti, they can often be found in Mereldar.]]
IMAGOdb.npcs.CAT_LIGHT["the_great_kyron_midnight"].zones = {"Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["the_great_kyron_midnight"].source = "Wylariâ"
IMAGOdb.npcs.CAT_LIGHT["the_great_kyron_midnight"].timeline = {
    {
        era = "Pre-TWW",
        text = [[Served as an overseer in the Arathi army. Joined the Arathi expedition to Hallowfall some time before the events in Khaz Algar.]],
    },
    {
        era = "TWW",
        text = [[Fought the Kaheti nerubians alongside Faerin Lothar, Anduin Wrynn, and an adventurer at the Aegis Wall. Shortly afterward, they assisted Anduin and Faerin in rekindling the Dawntower.]],
    },
    {
        era = "Midnight",
        text = [[Kyron was part of the Vanguard of the Light that defended Parhelion Plaza during the Devouring Host's attack.]],
    }
}


IMAGOdb.npcs.CAT_LIGHT["high_prelate_rata_midnight"].name = "High Prelate Rata"
IMAGOdb.npcs.CAT_LIGHT["high_prelate_rata_midnight"].race = "Zandalari troll"
IMAGOdb.npcs.CAT_LIGHT["high_prelate_rata_midnight"].lore = [[The Zandalari do not worship the Holy Light like other cultures do, but the prelates channel it through the power bestowed upon them by the loa. Rata, High Prelate and leader of the order, has always been one of its most faithful members. 

When Rezan, Loa of Kings, was slain by the traitorous Prophet Zul, most of the prelates lost their connection to the Light and were forced to leave the order. Rata retained her abilities and fought stalwartly, first under King Rastakhan's and then under Queen Talanji's orders. 

With the Sunwell on the brink of destruction, Zandalar's most prominent paladin answers the call for help.]]
IMAGOdb.npcs.CAT_LIGHT["high_prelate_rata_midnight"].zones = {"Silvermoon City", "Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_LIGHT["high_prelate_rata_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["high_prelate_rata_midnight"].timeline = {
    {
        era = "BfA",
        text = [[Led the prelates during the Fourth War as the main protectors of King Rastakhan. The order was severely weakened after Rezan's death, with many members losing their connection to the Light. Rata pledged her support to Queen Talanji and joined the Zanchuli Council after the king's death.]],
    },
    {
        era = "DF",
        text = [[Traveled to the Dragon Isles after Tyr's reforging.]],
    },
    {
        era = "TWW",
        text = [[Joined the Horde forces on Khaz Algar and fought against the nerubians in Hallowfall. Learned about the Arathi's faith from Great Kyron.]],
    },
    {
        era = "Midnight",
        text = [[Was summoned by the Sunwell and fought against the Void on the Isle of Quel'Danas.]],
    }
}

IMAGOdb.npcs.CAT_LIGHT["gidwin_goldbraids_midnight"].name = "Gidwin Goldbraids"
IMAGOdb.npcs.CAT_LIGHT["gidwin_goldbraids_midnight"].race = "Dwarf"
IMAGOdb.npcs.CAT_LIGHT["gidwin_goldbraids_midnight"].lore = [[Wanting to become a paladin since he was a lad, Gidwin and his best friend Tarenar Sunstrike pretended their entire childhoods to be heroes. At Light's Hope Chapel, they made that dream reality and joined the Argent Crusade. 

Unlike Tarenar, Gidwin - "Giddy" to his friends - is meticulous when it comes to his training. He keeps his armor and weapons in pristine condition, diligently studies texts of the Holy Light, and takes his duties seriously. Outside of battle, however, he is every bit as chaotic as his best friend, especially when drinks are involved.]]
IMAGOdb.npcs.CAT_LIGHT["gidwin_goldbraids_midnight"].zones = {"Silvermoon City", "Parhelion Plaza", "Isle of Quel'Danas", "Arcantina"}
IMAGOdb.npcs.CAT_LIGHT["gidwin_goldbraids_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["gidwin_goldbraids_midnight"].timeline = {
    {
        era = "Cata",
        text = [[Traveled with Tarenar on Fiona's caravan to become paladins at Light's Hope Chapel. Left to fight alone after Tarenar didn't take their mission seriously, but was caught and almost made a death knight by the Scourge. After being rescued, he forgave his friend and both were accepted into the Argent Crusade.]],
    },
    {
        era = "WoD",
        text = [[Accompanied Fiona and Tarenar to Draenor. Was poisoned and paralyzed during a botani attack, but Fiona nursed him back to health.]],
    },
    {
        era = "Legion",
        text = [[Joined the reformed Knights of the Silver Hand and fought against the Burning Legion on the Broken Shore.]],
    },
    {
        era = "Pre-BfA",
        text = [[Celebrated the Legion's defeat with Tarenar by running up enormous bar tabs in Silvermoon City, Tarenar's home. Had to sneak out when the Fourth War erupted.]],
    },
    {
        era = "DF",
        text = [[Went traveling with Fiona once more on the Dragon Isles.]],
    },
    {
        era = "Midnight",
        text = [[Answered the Sunwell's call to defend Silvermoon. Finally settled the mountain of drinking debts he and Tarenar had accumulated over the years. Since most inns in Quel'Thalas had long since banned them, the Arcantina became their new favorite establishment.]],
    }
}

-- MEHLAR DAWNBLADE --
IMAGOdb.npcs.CAT_LIGHT["mehlar_daemmerklinge_midnight"].name = "Mehlar Dawnblade"
IMAGOdb.npcs.CAT_LIGHT["mehlar_daemmerklinge_midnight"].aliases = {"Mehlar"}
IMAGOdb.npcs.CAT_LIGHT["mehlar_daemmerklinge_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_LIGHT["mehlar_daemmerklinge_midnight"].lore = [[Once a student of Uther the Lightbringer, Mehlar Dawnblade was a paladin of the Silver Hand before the Third War. He was known to follow a strict moral codex and heeded the commands of the order to the letter. When Uther's most prominent pupil – Arthas Menethil – strayed from the path of the Light and decimated Mehlar's homeland of Quel'Thalas, the blood elf's compassion turned into rage and a desire for vengeance.

He joined the Blood Knights under Lady Liadrin and fought in exemplary unity with his fellow paladins against the Scourge. He defiled Uther's tomb in a fit of rage, only to be confronted by the spirit of his former mentor. Receiving only forgiveness from the fallen paladin, Mehlar vowed to rethink his outlook and now tries to not be swayed by hatred as easily anymore.]]
IMAGOdb.npcs.CAT_LIGHT["mehlar_daemmerklinge_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["mehlar_daemmerklinge_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["mehlar_daemmerklinge_midnight"].timeline = IMAGOdb.timelines.MEHLAR_DAEMMERKLINGE

IMAGOdb.npcs.CAT_LIGHT["danath_trollbann_midnight"].name = "Danath Trollbane"
IMAGOdb.npcs.CAT_LIGHT["danath_trollbann_midnight"].aliases = {"Danath"}
IMAGOdb.npcs.CAT_LIGHT["danath_trollbann_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["danath_trollbann_midnight"].lore = "The rightful ruler of the kingdom of Stromgarde and longtime hero of the Alliance. Danath Trollbane has fought and bled for humankind since the days of the Second War. A member of the Sons of Lothar, Danath built close ties with his compatriots in their time beyond the Dark Portal. Having returned to Azeroth to take up the mantle of King of Stromgarde, Danath seeks to lead his people back to their former glory."
IMAGOdb.npcs.CAT_LIGHT["danath_trollbann_midnight"].zones = {"Arcantina", "Burning Steppes", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["danath_trollbann_midnight"].source = ""
IMAGOdb.npcs.CAT_LIGHT["danath_trollbann_midnight"].timeline = IMAGOdb.timelines.DANATH_TROLLBANN

IMAGOdb.npcs.CAT_LIGHT["anduin_wrynn_midnight"].name = "Anduin Wrynn"
IMAGOdb.npcs.CAT_LIGHT["anduin_wrynn_midnight"].aliases = {"Anduin Llane Wrynn", "King Anduin", "Little Lion"}
IMAGOdb.npcs.CAT_LIGHT["anduin_wrynn_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["anduin_wrynn_midnight"].lore = [[The High King-in-absentia of the Alliance, Anduin Llane Wrynn feels like he has become a mere shadow of his former radiant self.

He used to wield the light like few others, healing entire battlefields and consequently inspiring his people to fight on as a staunch defender of justice, tolerance and peace.  That changed when he was dominated by the Jailer and forced to help unravel the world he had sworn to protect while fully aware but unable to control his actions. Even after breaking free, he could not escape the fear that he was capable of such evil deeds, and something in Anduin broke.  He vanished for years, leaving his people and kingdom behind.

Now, with Xal'atath threatening everything he holds dear, Anduin has finally returned into the fray, slowly starting to gain back his confidence and his faith in the Light.]]
IMAGOdb.npcs.CAT_LIGHT["anduin_wrynn_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["anduin_wrynn_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["anduin_wrynn_midnight"].timeline = IMAGOdb.timelines.ANDUIN_WRYNN

-- HIGH EXARCH TURALYON --
IMAGOdb.npcs.CAT_LIGHT["turalyon_midnight"].name = "High Exarch Turalyon"
IMAGOdb.npcs.CAT_LIGHT["turalyon_midnight"].aliases = {"Turalyon"}
IMAGOdb.npcs.CAT_LIGHT["turalyon_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["turalyon_midnight"].lore = [[One of the first paladins of the Order of the Silver Hand, Turalyon became one of the Alliance's most famous war heroes – and one of the most admired. He fought as second-in-command to Anduin Lothar himself and, after the commander fell, it was Turalyon who decided the final battle against the orcish Horde in favor for the Alliance and the Holy Light. 

It was in the Second War that he met the woman he would share his life with – Alleria Windrunner. In the midst of all the fighting, the two became three. Yet when Turalyon and Alleria ventured into the orcish homeworld to stop the Horde once and for all, they made the difficult choice to leave their son Arator behind on Azeroth, knowing they would perhaps never see him grow up.

In the end, Draenor shattered and the couple were whisked away to fight for the Army of the Light in a thousand year long war against the Burning Legion. Turalyon thus became immortal, a Lightforged bulwark for justice and righteousness. Alleria, however, embraced the magic of the Void, a force of pure Evil in Turalyon's eyes.

Now, with the Burning Legion defeated, Turalyon and Alleria are back on Azeroth, on a world changed. Trying to reconnect with a son they don't know, trying to come to terms with how they've drifted so far apart as lovers, and most of all, trying to save their world once again.]]
IMAGOdb.npcs.CAT_LIGHT["turalyon_midnight"].zones = {"The Voidspire", "Eversong Woods", "Isle of Quel'Danas", "Voidstorm", "Parhelion Plaza", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["turalyon_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["turalyon_midnight"].timeline = IMAGOdb.timelines.TURALYON

IMAGOdb.npcs.CAT_LIGHT["prophet_velen_midnight"].name = "Prophet Velen"
IMAGOdb.npcs.CAT_LIGHT["prophet_velen_midnight"].aliases = {"Velen"}
IMAGOdb.npcs.CAT_LIGHT["prophet_velen_midnight"].race = "Draenei"
IMAGOdb.npcs.CAT_LIGHT["prophet_velen_midnight"].lore = [[Admired and trusted by the people of Azeroth, the old prophet Velen has led the draenei for over thirteen millennia. A chosen of the naaru, he has been granted the gift of foresight through visions of the Light itself. These visions have on more than one occasion not only saved his people's lives, but also have granted him confidence to believe in a future where evil will eventually be vanquished from the cosmos.

Velen's faith in the Light is unbreakable, and his earnestness and good nature have inspired his beliefs in both friends and even opponents – notably Anduin Wrynn and Lady Liadrin respectively.

It comes as no surprise then, that the Sunwell has called to him for aid. After all, Velen had restored it from corruption once before... and he will not let it darken again.]]
IMAGOdb.npcs.CAT_LIGHT["prophet_velen_midnight"].zones = {"Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["prophet_velen_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["prophet_velen_midnight"].timeline = IMAGOdb.timelines.PROPHET_VELEN

-- CALIA MENETHIL --
IMAGOdb.npcs.CAT_LIGHT["calia_menethil_midnight"].name = "Calia Menethil"
IMAGOdb.npcs.CAT_LIGHT["calia_menethil_midnight"].aliases = {"the Pallid Lady"}
IMAGOdb.npcs.CAT_LIGHT["calia_menethil_midnight"].race = "Undead Human"
IMAGOdb.npcs.CAT_LIGHT["calia_menethil_midnight"].lore = [[To call the Pallid Lady a politically controversial figure would be an understatement. She is the sister of the infamous Arthas Menethil and only remaining heir to the throne of Lordaeron, which is now in Forsaken hands - the very undead hands of Arthas' primary victims. As a member of the Alliance and a priestess of the Light, Calia had denied to wish to rule over her people.

That changed, however, when she herself was killed and raised into undeath by the naaru Saa'ra. She joined the Horde and became a ruling member of the Forsaken's Desolate Council. Even though she has since shown a desire to aid her people, even putting herself in danger for the cause, it does seem like she has yet to earn the Forsaken's full trust. 

For now though, her political ambitions – whatever they may be – have to wait. The Light has called her to Silvermoon and Calia has answered the call.]]
IMAGOdb.npcs.CAT_LIGHT["calia_menethil_midnight"].zones = {"Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["calia_menethil_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["calia_menethil_midnight"].timeline = IMAGOdb.timelines.CALIA_MENETHIL

IMAGOdb.npcs.CAT_LIGHT["taelia_fordragon_midnight"].name = "Taelia Fordragon"
IMAGOdb.npcs.CAT_LIGHT["taelia_fordragon_midnight"].aliases = {"Taelia"}
IMAGOdb.npcs.CAT_LIGHT["taelia_fordragon_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["taelia_fordragon_midnight"].lore = [[A friendly and headstrong young woman, Taelia was born in Lordaeron shortly before the wars against the Horde broke out. After losing her mother in the conflict, her father Bolvar sent her to the kingdom of Kul Tiras for her own safety.

She became a paladin and fought loyally for House Proudmoore, for her new home, and afterwards for the Alliance.

Taelia is an open-minded individual, being best friends with the former pirate Flynn Fairwind, and even reconnecting happily with her father Bolvar after finding out that he had been made the Lich King.

Now, the Sunwell has called Taelia to lend her strength to Silvermoon's defense.]]
IMAGOdb.npcs.CAT_LIGHT["taelia_fordragon_midnight"].zones = {"Eversong Woods", "Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["taelia_fordragon_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["taelia_fordragon_midnight"].timeline = IMAGOdb.timelines.TAELIA_FORDRAGON

IMAGOdb.npcs.CAT_LIGHT["moira_thaurissan_midnight"].name = "Moira Thaurissan"
IMAGOdb.npcs.CAT_LIGHT["moira_thaurissan_midnight"].aliases = {"Moira Bronzebeard", "Dark Iron Queen"}
IMAGOdb.npcs.CAT_LIGHT["moira_thaurissan_midnight"].race = "Dwarf"
IMAGOdb.npcs.CAT_LIGHT["moira_thaurissan_midnight"].lore = [[A long-standing and respected leader of the Bronzebeard and the Dark Iron Clans, Queen Moira had not always held such a favorable position among Alliance ranks. Her days of meddling in civil wars are in the past now, though.

Born as the sole heir to former King Magni and as the widow of the late Emperor Dagran Thaurissan of Blackrock Mountain, she is a member of two out of the three ruling clans of the dwarves. Her son, Dagran II is poised to be the next king of all the clans, once he comes of age.

Never having seen eye to eye with her father, the two of them have recently made the first steps towards reconciliation. Their family time has been promptly interrupted by Xal'atath's attack - first on Dalaran and now, on Silvermoon.]]
IMAGOdb.npcs.CAT_LIGHT["moira_thaurissan_midnight"].zones = {"Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["moira_thaurissan_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["moira_thaurissan_midnight"].timeline = IMAGOdb.timelines.MOIRA_THAURISSAN

IMAGOdb.npcs.CAT_LIGHT["hauptmann_fareeya_midnight"].name = "Captain Fareeya"
IMAGOdb.npcs.CAT_LIGHT["hauptmann_fareeya_midnight"].aliases = {"Fareeya"}
IMAGOdb.npcs.CAT_LIGHT["hauptmann_fareeya_midnight"].race = "Lightforged Draenei"
IMAGOdb.npcs.CAT_LIGHT["hauptmann_fareeya_midnight"].lore = [[Second-in-command to High Exarch Turalyon, Fareeya is one of the leaders of the Army of the Light. A survivor of the Burning Legion, she originally escaped Argus with Prophet Velen but later her path would lead her back to her corrupted homeworld. With her most elite draenei soldiers she was adamant to not flee, but to stand and fight. 

Her troop became the Army of the Light and they gave themselves fully to the Light - in both body and soul. The holy crusade grew and inspired even other races to join the mission. In the end, and with the help of the Champions of Azeroth, the demons were finally defeated. Fareeya didn't plan on resting on her laurels though and followed Turalyon into the ranks of the Alliance on Azeroth, determined to keep on fighting for all that is holy and good.]]
IMAGOdb.npcs.CAT_LIGHT["hauptmann_fareeya_midnight"].zones = {"Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["hauptmann_fareeya_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["hauptmann_fareeya_midnight"].timeline = IMAGOdb.timelines.HAUPTMANN_FAREEYA

-- DELAS MOONFANG --
IMAGOdb.npcs.CAT_LIGHT["delas_moonfang_midnight"].name = "Delas Moonfang"
IMAGOdb.npcs.CAT_LIGHT["delas_moonfang_midnight"].aliases = {"Delas"}
IMAGOdb.npcs.CAT_LIGHT["delas_moonfang_midnight"].race = "Night elf"
IMAGOdb.npcs.CAT_LIGHT["delas_moonfang_midnight"].lore = [[Delas Moonfang has been a priestess of Elune for almost the entirety of her long life. Growing up during the War of the Ancients, she took on the holy profession to aid others – because aid was clearly needed in a time of demons. She committed her life to healing and to the study of demons, and she even learned to speak Eredun.

When the Legion returned, Delas wasted no time to join the Conclave under Alonsus Faol. Her true path in the Light lay in becoming the first night elven paladin though, as she found out when she met the Highlord of the Silver Hand. After all these millennia, she finally feels like she can accomplish her true destiny.]]
IMAGOdb.npcs.CAT_LIGHT["delas_moonfang_midnight"].zones = {"Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_LIGHT["delas_moonfang_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["delas_moonfang_midnight"].timeline = IMAGOdb.timelines.DELAS_MOONFANG

IMAGOdb.npcs.CAT_LIGHT["lord_grayson_schattenbruch_midnight"].name = "Lord Grayson Shadowbreaker"
IMAGOdb.npcs.CAT_LIGHT["lord_grayson_schattenbruch_midnight"].aliases = {"Grayson Shadowbreaker"}
IMAGOdb.npcs.CAT_LIGHT["lord_grayson_schattenbruch_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["lord_grayson_schattenbruch_midnight"].lore = [[The primary human paladin trainer and a veteran fighter of the Order of the Silver Hand, Lord Grayson Shadowbreaker has been an indispensable asset to the Alliance for decades. 

He is not only in charge of training new recruits and helping them become beacons of righteousness, but he also oversees threats all across Azeroth and sends out reinforcements as needed.

Shadowbreaker can be considered a paladin of very traditional values and still holds the undead in high contempt. Never one to be too friendly or forgiving with both his trainees and his foes, he ultimately wants what is best for the Alliance and for the Order of the Silver Hand.]]
IMAGOdb.npcs.CAT_LIGHT["lord_grayson_schattenbruch_midnight"].zones = {"Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_LIGHT["lord_grayson_schattenbruch_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["lord_grayson_schattenbruch_midnight"].timeline = IMAGOdb.timelines.LORD_GRAYSON_SCHATTENBRUCH

-- EADRIC THE PURE --
IMAGOdb.npcs.CAT_LIGHT["eadric_der_reine_midnight"].name = "Eadric the Pure"
IMAGOdb.npcs.CAT_LIGHT["eadric_der_reine_midnight"].aliases = {"Eadric"}
IMAGOdb.npcs.CAT_LIGHT["eadric_der_reine_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["eadric_der_reine_midnight"].lore = [[A paladin and quartermaster of the Argent Crusade, Eadric is mostly known for his contributions to the order during the war against the Lich King in Northrend. Tensions between the Alliance and the Horde were rising once again, and Highlord Tirion Fordring proposed to host a friendly tournament to prevent a conflict. His champion Eadric was the one responsible for organizing most of this tournament.

He has since mostly been stationed in Northrend, but as any true paladin, he goes where the Light calls him.]]
IMAGOdb.npcs.CAT_LIGHT["eadric_der_reine_midnight"].zones = {"Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["eadric_der_reine_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["eadric_der_reine_midnight"].timeline = IMAGOdb.timelines.EADRIC_DER_REINE

-- YALIA SAGEWHISPER --
IMAGOdb.npcs.CAT_LIGHT["yalia_weisenwisper_midnight"].name = "Yalia Sagewhisper"
IMAGOdb.npcs.CAT_LIGHT["yalia_weisenwisper_midnight"].aliases = {"Yalia"}
IMAGOdb.npcs.CAT_LIGHT["yalia_weisenwisper_midnight"].race = "Pandaren"
IMAGOdb.npcs.CAT_LIGHT["yalia_weisenwisper_midnight"].lore = [[Raised as a fisherwoman, trained as a Shado-Pan and serving as a priest and alchemist, Yalia is a woman of many talents. After having to leave her family behind at a young age, she has dedicated most of her life to healing her fellow pandaren from the Shado-Pan Monastary in Kun-Lai Summit.

After lending her support to combat foes such as Lei Shen and the Burning Legion, Yalia's wisdom and need to make the world a better place were recognized by the Holy Light. She now has been called to Silvermoon to once again fight for her world.]]
IMAGOdb.npcs.CAT_LIGHT["yalia_weisenwisper_midnight"].zones = {"Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["yalia_weisenwisper_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["yalia_weisenwisper_midnight"].timeline = IMAGOdb.timelines.YALIA_WEISENWISPER

-- FIONA --
IMAGOdb.npcs.CAT_LIGHT["fiona_midnight"].name = "Fiona"
IMAGOdb.npcs.CAT_LIGHT["fiona_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["fiona_midnight"].race = "Worgen"
IMAGOdb.npcs.CAT_LIGHT["fiona_midnight"].lore = [[Caring and loyal, this worgen woman and her caravan have been traveling all over Azeroth for many years. She earns her livelihood as a traveling herbalist and healer, but her heart yearns for the companionship of the different people she meets on her adventures. She is all too happy to lend travelers a ride on her stagecoach and can't walk past souls in need without stopping to help however she can. It is a simple life, but Fiona is very fulfilled by it.  

Her two closest friends are the paladins Tarenar Sunstrike and Gidwin Goldbraids, who frequently accompany her.

The Sunwell has sensed her compassion and willingness to help others and has called her to Silvermoon to defend it. As always, Fiona will do whatever she can.]]
IMAGOdb.npcs.CAT_LIGHT["fiona_midnight"].zones = {"Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_LIGHT["fiona_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["fiona_midnight"].timeline = IMAGOdb.timelines.FIONA

-- LOTHRAXION --
IMAGOdb.npcs.CAT_LIGHT["lothraxion_midnight"].name = "Lothraxion"
IMAGOdb.npcs.CAT_LIGHT["lothraxion_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["lothraxion_midnight"].race = "Lightforged Nathrezim"
IMAGOdb.npcs.CAT_LIGHT["lothraxion_midnight"].lore = [[It is said that dreadlords are cruel, sadistic and manipulative creatures. Either spies from the Burning Legion or from the realms of death itself. Shapeshifters that infiltrate their enemies' ranks and turn even the noblest souls against one another. It is said they can't be trusted.

Lothraxion is the one exception to this truth. He had destroyed countless worlds in service of Sargeras' grand vision and made the Void his greatest enemy. When the  demons' crusade brought him to meet the draenei, Lothraxion was swayed to betray his former masters. He joined the Army of the Light and became Lightforged.

Having known all the horrors that both the Fel and the Void had wrought across the cosmos, Lothraxion accepts no compromises in dealing with any creatures that belong to these forces. He is convinced that only the Light can defeat these evils. Now, under his High Exarch Turalyon's command, Lothraxion has been called to the Sunwell to once again fight against the forces of darkness.]]
IMAGOdb.npcs.CAT_LIGHT["lothraxion_midnight"].zones = {"Isle of Quel'Danas", "Nexus-Point Xenas", "Parhelion Plaza", "Silvermoon City", "Voidstorm"}
IMAGOdb.npcs.CAT_LIGHT["lothraxion_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["lothraxion_midnight"].timeline = IMAGOdb.timelines.LOTHRAXION

IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].name = "Archbishop Alonsus Faol"
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].aliases = {"Alonsus Faol"}
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].race = "Undead"
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].lore = [[Formerly the Archbishop of the Church of the Holy Light, Alonsus Faol was arguably the most revered man in Lordaeron. When the Horde first invaded Azeroth, it was Faol who trained and annointed the first paladins – a decision that won the war for the Alliance. Proud of his achievements, the elderly bishop died peacefully.

Arthas Menethil would not let him rest and resurrected him as a mindless minion of the Scourge. When Alonsus finally broke free of the fallen paladin's control, he was shunned by the Alliance, hunted by radical servants of the Light, and met with terrible pain whenever he himself used holy magic. He retreated from the world for years.

When the Legion invaded, Alonsus could not stand by and watch. Now leading the Conclave, uniting the priestly orders, he helped find various artifacts to combat the demons. One these artifacts was the Blade of the Black Empire – Xal'atath.

Now, Alonsus fights for the Sunwell and the Light, and to correct his mistake.]]
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].zones = {"Burning Steppes", "Arathi Highlands", "Isle of Quel'Danas", "Eastern Plaguelands", "Parhelion Plaza", "Silvermoon City", "Tirisfal Glades"}
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["alonsus_faol_midnight"].timeline = IMAGOdb.timelines.ALONSUS_FAOL

-- TAHU SAGEWIND --
IMAGOdb.npcs.CAT_LIGHT["tahu_sagewind_midnight"].name = "Tahu Sagewind"
IMAGOdb.npcs.CAT_LIGHT["tahu_sagewind_midnight"].aliases = {"Tahu"}
IMAGOdb.npcs.CAT_LIGHT["tahu_sagewind_midnight"].race = "Tauren"
IMAGOdb.npcs.CAT_LIGHT["tahu_sagewind_midnight"].lore = [[The tauren have practiced druidism since the dawn of their people. The magic showed reverence to Azeroth's moon, Mu'sha, one of the eyes of the Earth Mother. Tahu and his friend Aponi Brightmane pondered the nature of the Earth Mother's other eye, An'she – the Sun – and wondered why the tauren had been neglecting him for so long. Thus were sown the first seeds to new paths for their people.

While Aponi became a paladin, Tahu founded the priestly order of the Seers and both paid heed to An'she's teachings of the Light. Since then he has trained countless priests and lent his aid to Azeroth on many occasions.]]
IMAGOdb.npcs.CAT_LIGHT["tahu_sagewind_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["tahu_sagewind_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["tahu_sagewind_midnight"].timeline = IMAGOdb.timelines.TAHU_SAGEWIND

-- APONI BRIGHTMANE --
IMAGOdb.npcs.CAT_LIGHT["aponi_lichtmaehne_midnight"].name = "Aponi Brightmane"
IMAGOdb.npcs.CAT_LIGHT["aponi_lichtmaehne_midnight"].aliases = {"Aponi"}
IMAGOdb.npcs.CAT_LIGHT["aponi_lichtmaehne_midnight"].race = "Tauren"
IMAGOdb.npcs.CAT_LIGHT["aponi_lichtmaehne_midnight"].lore = [[During the war against the Lich King in Northrend, the tauren warrior Aponi Brightmane had an epiphany. She wanted to help her people and the Horde with more than just her strength. After a discussion with her friend Tahu Sagewind, Aponi incorporated the teachings of the deity An'she – the sun – into her fighting. Thus, she became the first tauren paladin.

Since joining the Order of the Silver Hand in battle during the third and final invasion of the Burning Legion, Aponi's Sunwalkers can be found far and wide across Azeroth, helping anyone in need.]]
IMAGOdb.npcs.CAT_LIGHT["aponi_lichtmaehne_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["aponi_lichtmaehne_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["aponi_lichtmaehne_midnight"].timeline = IMAGOdb.timelines.APONI_LICHTMAEHNE

-- WAR CHAPLAIN SENN --
IMAGOdb.npcs.CAT_LIGHT["war_chaplain_senn_midnight"].name = "War Chaplain Senn"
IMAGOdb.npcs.CAT_LIGHT["war_chaplain_senn_midnight"].aliases = {"Chaplain Senn", "Senn" }
IMAGOdb.npcs.CAT_LIGHT["war_chaplain_senn_midnight"].race = "Lightforged draenei"
IMAGOdb.npcs.CAT_LIGHT["war_chaplain_senn_midnight"].lore = [[A loyal lieutenant to Turalyon, Senn has fought cosmic evil in service of the Army of the Light for hundreds of years. She has developed an intense hatred towards the forces of the Void and can barely contain her disgust towards her ren'dorei allies. 

Now, she has been summoned by the Sunwell to fight for the Light once more. Senn isn't interested in defending Silvermoon City though. Her priorities lie first and foremost in vanquishing Xal'atath and her minions, no matter the costs.]]
IMAGOdb.npcs.CAT_LIGHT["war_chaplain_senn_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza", "Silvermoon City", "The Voidspire", "Voidstorm"}
IMAGOdb.npcs.CAT_LIGHT["war_chaplain_senn_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["war_chaplain_senn_midnight"].timeline = IMAGOdb.timelines.WAR_CHAPLAIN_SENN

IMAGOdb.npcs.CAT_LIGHT["faerin_lothar_midnight"].name = "Faerin Lothar"
IMAGOdb.npcs.CAT_LIGHT["faerin_lothar_midnight"].aliases = {"Faerin"}
IMAGOdb.npcs.CAT_LIGHT["faerin_lothar_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["faerin_lothar_midnight"].lore = [[This young paladin is a beacon of hope and optimism to her fellow soldiers, often being the first to rush into battle, protecting others with her shield and her faith in the Light. Faerin had always had a knack for danger, sneaking aboard the airship of the Arathi expedition to Hallowfall as just a mere child. In the following crash landing she lost her eye and arm but learned to fight on and live without them.

Not having lived long in the Empire, Faerin is not interested in returning to her birthplace and instead wants to explore the rest of the world, especially the places important to her heritage as an Arathi and a Lothar. However, that endeavor will have to wait until after the Sunwell is secured.]]
IMAGOdb.npcs.CAT_LIGHT["faerin_lothar_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza", "Silvermoon City"}
IMAGOdb.npcs.CAT_LIGHT["faerin_lothar_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["faerin_lothar_midnight"].timeline = IMAGOdb.timelines.FAERIN_LOTHAR

-- GENERAL AMAIS BELLAMY --
IMAGOdb.npcs.CAT_LIGHT["general_amias_bellamy_midnight"].name = "General Amias Bellamy"
IMAGOdb.npcs.CAT_LIGHT["general_amias_bellamy_midnight"].aliases = {"Amias Bellamy"}
IMAGOdb.npcs.CAT_LIGHT["general_amias_bellamy_midnight"].race = "Arathi"
IMAGOdb.npcs.CAT_LIGHT["general_amias_bellamy_midnight"].lore = [[Few can say that their faith has held such a significant role in their lives as the Arathi of Hallowfall. Bellamy, like many of her fellow paladins, undertook the dangerous expedition across the sea to follow a vision of the Light.

In the end, she became stranded under Khaz Algar, the Sacred Flame and their star Beledar the only brightness in their new lives of constant darkness and danger. Faith was no longer a mere comfort – it was what kept her alive.

Of course she was summoned by the Sunwell after keeping Hallowfall safe.

Of course she will keep fighting for the Light and only for the Light.

Of course every being of the Void should be considered an enemy.]]
IMAGOdb.npcs.CAT_LIGHT["general_amias_bellamy_midnight"].zones = {"Isle of Quel'Danas", "Silvermoon City", "The Voidspire", "Voidstorm"}
IMAGOdb.npcs.CAT_LIGHT["general_amias_bellamy_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["general_amias_bellamy_midnight"].timeline = IMAGOdb.timelines.GENERAL_AMIAS_BELLAMY

IMAGOdb.npcs.CAT_LIGHT["arator_midnight"].name = "Arator the Redeemer"
IMAGOdb.npcs.CAT_LIGHT["arator_midnight"].aliases = {"Arator", "Arator Windrunner"}
IMAGOdb.npcs.CAT_LIGHT["arator_midnight"].race = "Half-Elf"
IMAGOdb.npcs.CAT_LIGHT["arator_midnight"].lore =
[[
When his parents Alleria Windrunner and Turalyon left for Draenor to save Azeroth, they left their newborn behind. Raised by family, Arator only knew his parents through legend. As the child of two of the Alliance's most famous war heroes, Arator has always struggled to step out of their shadows and find his own destiny. 
    
Choosing to emulate his father, he became a paladin for the Alliance and rose up in the ranks by showing true strength and faith in the Light. Now reunited with his parents, Arator struggles to hold his family together as they are pulled in different directions.]]
IMAGOdb.npcs.CAT_LIGHT["arator_midnight"].zones = {"Amirdrassil", "Arcantina", "Burning Steppes", "Arathi Highlands", "The Void Spire", "Harandar", "Den of Masters", "Eversong Woods", "Isle of Quel'Danas", "Voidstorm", "Eastern Plaguelands", "Parhelion Plaza", "Silvermoon City", "Zul'Aman"}
IMAGOdb.npcs.CAT_LIGHT["arator_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["arator_midnight"].timeline = IMAGOdb.timelines.ARATOR

-- NOLAKI --
IMAGOdb.npcs.CAT_LIGHT["nolaki_midnight"].name = "Nolaki"
IMAGOdb.npcs.CAT_LIGHT["nolaki_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["nolaki_midnight"].race = "Zandalari troll"
IMAGOdb.npcs.CAT_LIGHT["nolaki_midnight"].lore = [[Easy to amuse and hard to anger, this Zandalari woman became a paladin under Ra'wani Kanae. Being young, she stayed behind when the Alliance attacked Dazar'alor because she was convinced that one warrior more or less wouldn't make a difference in the battle. Her demeanor changed when both her mentor and King Rastakhan were slain.

Since then, Nolaki matured a lot and dedicated her life to putting others before herself. That, to her, is what makes a paladin and she joined the Tyr's Guard as the Exemplary of Sacrifice, ready to put herself in between the enemy and whoever would need her protection.]]
IMAGOdb.npcs.CAT_LIGHT["nolaki_midnight"].zones = {"Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_LIGHT["nolaki_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["nolaki_midnight"].timeline = IMAGOdb.timelines.NOLAKI

-- VALUNEI --
IMAGOdb.npcs.CAT_LIGHT["valunei_midnight"].name = "Valunei"
IMAGOdb.npcs.CAT_LIGHT["valunei_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["valunei_midnight"].race = "Lightforged draenei"
IMAGOdb.npcs.CAT_LIGHT["valunei_midnight"].lore = [[Valunei has always been opposed to fighting. When the Burning Legion conquered her homeworld though, she was left with no choice. The war was won in the end, but Valunei had lost her best friend to the demons and had fought for so long that she didn't remember who she was before it all started.

Joining her brethren on Azeroth, Valunei felt without purpose. She wandered this new world trying to help as many people as she could, and slowly finding hope again. The kindness she showed drew the attention of Travard and thus, Valunei was recruited into the renewed Tyr's Guard as the Exemplar of Compassion.]]
IMAGOdb.npcs.CAT_LIGHT["valunei_midnight"].zones = {"Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_LIGHT["valunei_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["valunei_midnight"].timeline = IMAGOdb.timelines.VALUNEI

-- MARIELLA WARD --
IMAGOdb.npcs.CAT_LIGHT["mariella_ward_midnight"].name = "Mariella Ward"
IMAGOdb.npcs.CAT_LIGHT["mariella_ward_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["mariella_ward_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["mariella_ward_midnight"].lore = [[Known as Mariella "the Heretic", she once served the Scarlet Onslaught. Disagreeing with their zealous ways to wield the Light, she was sentenced to death for her disobedience. Arriving to a timely rescue, the High Priest sent by Alonsus Faol was able to save her, and she joined the Conclave.

Now, having found forgiveness for her deeds, she has been summoned by the Sunwell to protect Silvermoon as a part of the Vanguard of the Light.]]
IMAGOdb.npcs.CAT_LIGHT["mariella_ward_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["mariella_ward_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["mariella_ward_midnight"].timeline = IMAGOdb.timelines.MARIELLA_WARD

-- HADWIN --
IMAGOdb.npcs.CAT_LIGHT["hadwin_midnight"].name = "Hadwin"
IMAGOdb.npcs.CAT_LIGHT["hadwin_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["hadwin_midnight"].race = "Human"
IMAGOdb.npcs.CAT_LIGHT["hadwin_midnight"].lore = [[A burly man from humble origins and with a blunt attitude, Hadwin never thought about becoming a paladin. Like most Kul Tirans, he grew up worshipping the Tidemother. Ever since he was a small boy, watching fretfully as his mother's shop was robbed again and again whenever his father was out at sea, a burning desire for justice fueled his actions. 

He vowed to stand up for the people that needed a strong arm to defend them and he volunteered to become an inquisitor for the Order of Embers in Drustvar. There, he began to feel a strange connection to the Light, a connection he still can't quite explain. He began training as a paladin out of curiosity and to find out his true path in life. Now, he has become the Exemplar of Justice in the Tyr's Guard and the Sunwell recognized his good heart and summoned him to Silvermoon.]]
IMAGOdb.npcs.CAT_LIGHT["hadwin_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["hadwin_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["hadwin_midnight"].timeline = IMAGOdb.timelines.HADWIN

-- TALTHIS --
IMAGOdb.npcs.CAT_LIGHT["talthis_midnight"].name = "Talthis"
IMAGOdb.npcs.CAT_LIGHT["talthis_midnight"].aliases = {}
IMAGOdb.npcs.CAT_LIGHT["talthis_midnight"].race = "Blood elf"
IMAGOdb.npcs.CAT_LIGHT["talthis_midnight"].lore = [[Growing up during the Third War in Quel'Thalas changed Talthis' view on life and robbed him of a peaceful childhood. He came to the conclusion that the world was out of order, that the forces of evil and disarray like the Lich King and the Burning Legion had to be eliminated so that structure and harmony could return to the world.

He joined the Blood Knights to purge the remnants of the rampaging Scourge in the Dead Scar and later ventured to the Dragon Isles to stop the elemental disorder. He was recruited into the Tyr's Guard and felt a great appreciation for the titan philosophy of peace through order. Thus he became the Exemplar of Order and was content with his role in the grander scheme of things.]]
IMAGOdb.npcs.CAT_LIGHT["talthis_midnight"].zones = {"Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_LIGHT["talthis_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["talthis_midnight"].timeline = IMAGOdb.timelines.TALTHIS


IMAGOdb.npcs.CAT_LIGHT["vindicator_boros_midnight"].name = "Vindicator Boros"
IMAGOdb.npcs.CAT_LIGHT["vindicator_boros_midnight"].aliases = {"Boros"}
IMAGOdb.npcs.CAT_LIGHT["vindicator_boros_midnight"].race = "Draenei"
IMAGOdb.npcs.CAT_LIGHT["vindicator_boros_midnight"].lore = [[Both a leader of the Hand of Argus and a member of the Silver Hand, Boros has vowed to keep paladin traditions alive. He has proven a capable military commander in service of his people, the Draenei, multiple times but won't hesitate to pledge his hammer and faith to anyone in need.

Now, Vindicator Boros has been called by the Sunwell to combat the Void. As always, he can be counted on to fulfill his duty to the people of Azeroth.]]
IMAGOdb.npcs.CAT_LIGHT["vindicator_boros_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["vindicator_boros_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["vindicator_boros_midnight"].timeline = IMAGOdb.timelines.VINDICATOR_BOROS

IMAGOdb.npcs.CAT_LIGHT["sunwalker_dezco_midnight"].name = "Sunwalker Dezco"
IMAGOdb.npcs.CAT_LIGHT["sunwalker_dezco_midnight"].aliases = {"Dezco"}
IMAGOdb.npcs.CAT_LIGHT["sunwalker_dezco_midnight"].race = "Tauren"
IMAGOdb.npcs.CAT_LIGHT["sunwalker_dezco_midnight"].lore =
[[
Chieftain of the Dawnchaser tribe, Sunwalker Dezco is a steadfast tauren who reveres An'she, the sun, drawing his formidable power from her light. Having endured unimaginable personal tragedies that would break a lesser spirit, Dezco journeyed to distant lands in search of purpose. Though his travels have taken him across distant continents and even into the realms of the afterlife, the place he felt most at home was with the common people of Azeroth. 
    
Dedicated to service, Dezco stands as a seasoned veteran and wise elder among the Sunwalkers. As conflict brews anew, he serves as a guiding mentor, teaching allies that walking the path of the Light requires not only fervent zeal, but deep compassion as well.]]
IMAGOdb.npcs.CAT_LIGHT["sunwalker_dezco_midnight"].zones = {"Arathi Highlands"}
IMAGOdb.npcs.CAT_LIGHT["sunwalker_dezco_midnight"].source = "Lewi"
IMAGOdb.npcs.CAT_LIGHT["sunwalker_dezco_midnight"].timeline = IMAGOdb.timelines.SUNWALKER_DEZCO

-- AEONARA DAWNSHADE --
IMAGOdb.npcs.CAT_LIGHT["aeonara_dawnshade_midnight"].name = "Aeonara Dawnshade"
IMAGOdb.npcs.CAT_LIGHT["aeonara_dawnshade_midnight"].aliases = {"Aeonara"}
IMAGOdb.npcs.CAT_LIGHT["aeonara_dawnshade_midnight"].race = "Void elf"
IMAGOdb.npcs.CAT_LIGHT["aeonara_dawnshade_midnight"].lore = [[As the only known void elf paladin, Aeonara Dawnshade fights against the armies of the Void. She defended Telogrus Rift from the void ethereals of the Shadowguard, and later fought against Dimensius' forces at Manaforge Omega in K'aresh.

She has now been summoned as part of the Vanguard of the Light in order to defend the Sunwell from Xal'atath's Devouring Host.]]
IMAGOdb.npcs.CAT_LIGHT["aeonara_dawnshade_midnight"].zones = {"Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["aeonara_dawnshade_midnight"].source = "Travanoid"
IMAGOdb.npcs.CAT_LIGHT["aeonara_dawnshade_midnight"].timeline = IMAGOdb.timelines.AEONARA_DAWNSHADE

-- TARENAR SUNSTRIKE --
IMAGOdb.npcs.CAT_LIGHT["tarenar_sunstrike_midnight"].name = "Tarenar Sunstrike"
IMAGOdb.npcs.CAT_LIGHT["tarenar_sunstrike_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_LIGHT["tarenar_sunstrike_midnight"].lore = [[Since they were kids, Tarenar and his best friend Gidwin Goldbraids pretended to be heroes. As the 'Paladin Pals' they wanted to combat evil side by side. At Light's Hope Chapel, they made that dream reality and joined the Argent Crusade.

With his recklessness and tendency to not take things seriously, Tarenar frequently incites frustration in both Gidwin and their mutual friend Fiona. However, he never hesitates to make up for his mistakes and take responsibility.]]
IMAGOdb.npcs.CAT_LIGHT["tarenar_sunstrike_midnight"].zones = {"Arcantina", "Silvermoon City", "Isle of Quel'Danas", "Parhelion Plaza"}
IMAGOdb.npcs.CAT_LIGHT["tarenar_sunstrike_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["tarenar_sunstrike_midnight"].timeline = IMAGOdb.timelines.TARENAR_SUNSTRIKE

IMAGOdb.npcs.CAT_LIGHT["grand_artificer_romuul_midnight"].name = "Grand Artificer Romuul"
IMAGOdb.npcs.CAT_LIGHT["grand_artificer_romuul_midnight"].race = "Draenei"
IMAGOdb.npcs.CAT_LIGHT["grand_artificer_romuul_midnight"].lore = [[The leader of the artificers – draenei engineers and architects – and Velen's main confidant in the Exodar's organizational affairs, Romuul has stayed loyally at Velen's side since they first fled from Argus thousands of years ago. He was in charge of repairing, maintaining, and piloting the Vindicaar during the third invasion of the Burning Legion, and outfitted the vessel to be the base of operations of the Army of the Light even after the Legion's defeat.

During the Tishamaat, Velen and Romuul announced their plans for the construction of a new city on Azeroth, giving the draenei a chance to finally settle on a world they could once again call home. The work has to be put on hold, however, as the Grand Artificer has been called by the Sunwell to combat the Void. Ready to serve, he exchanges his chisel for his holy hammer and fights for the Light, for a new dawn for his people, and for all of Azeroth.]]
IMAGOdb.npcs.CAT_LIGHT["grand_artificer_romuul_midnight"].zones = {"Isle of Quel'Danas", "Parhelion Plaza", "Voidstorm"}
IMAGOdb.npcs.CAT_LIGHT["grand_artificer_romuul_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_LIGHT["grand_artificer_romuul_midnight"].timeline = IMAGOdb.timelines.GRAND_ARTIFICER_ROMUUL

-- CAT_NEUTRAL
IMAGOdb.npcs.CAT_NEUTRAL["allari_die_seelenfresserin_midnight"].name = "Allari the Souleater"
IMAGOdb.npcs.CAT_NEUTRAL["allari_die_seelenfresserin_midnight"].aliases = {"Allari"}

IMAGOdb.npcs.CAT_NEUTRAL["allari_die_seelenfresserin_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_NEUTRAL["allari_die_seelenfresserin_midnight"].lore = [[With a nearly unrivaled hatred for the Burning Legion, Allari the Souleater earned her moniker by using the mighty Scythe of Souls to entrap the souls of demons within it. This dangerous weapon communicates with her, pushing her to commit even more harm to her enemies and she frequently uses it as a torture device.

Yet even though her methods are extreme, Allari fights for the good of Azeroth. With the Legion's final defeat, she now has made it her mission to teach willing ren'dorei the ways of the demon hunters and aids them in the battle against the Void.]]
IMAGOdb.npcs.CAT_NEUTRAL["allari_die_seelenfresserin_midnight"].zones = {"Voidstorm", "K'aresh"}
IMAGOdb.npcs.CAT_NEUTRAL["allari_die_seelenfresserin_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["allari_die_seelenfresserin_midnight"].timeline = IMAGOdb.timelines.ALLARI_DIE_SEELENFRESSERIN

-- ALLERIA WINDRUNNER --
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].name = "Alleria Windrunner"
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].aliases = {"Alleria"}
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].race = "Void elf (former high elf)"
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].lore = [[Known to the people of Azeroth as one of the Alliance's greatest war heroes, Alleria has fought in the Second War and in the millennia-long crusade against the Burning Legion. She is many things - a mother, a partner, a hero, an older sister - but above all she is a huntress. Everything comes second to the mission before her and no price is too high to ensure the safety of her world. 

War is the only life she understands, and she finds more comfort and familiarity on the battlefield than in times of peace. When she lost her younger brother and her parents to the war against the Horde, Alleria blamed herself and charged recklessly into combat, chasing purpose through violence. She never truly recovered from the trauma of these losses. Having a family of her own with Turalyon and their son Arator, she can't bring herself to open up emotionally again, even though seeing the two men become strangers is hurting her to the core.

While fighting the Burning Legion, Alleria has found a weapon in the Void. She was infused with the fallen naaru L'ura and now wields her dark powers for the good of Azeroth. Always on the brink of falling to madness, with constant whispers assaulting her mind, Alleria has now set her mind on hunting Xal'atath. As with all her hunts, the pursuit has become an obsession and she won't rest until her foe lies defeated.]]
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].zones = {"The Voidspire", "Voidstorm"}
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["alleria_windrunner_midnight"].timeline = IMAGOdb.timelines.ALLERIA_WINDRUNNER


IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].name = "Decimus"
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].aliases = {}
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].race = "Domanaar"
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].lore = [[Charismatic, dangerous, malicious - all of these adjectives could be used to describe Decimus.

As all domanaar of the Voidstorm, he was subjugated to Xal'atath, recognizing her as the stronger being. Yet serving someone else wasn't something Decimus was planning on doing for much longer and thus they now enter a risky game - with the champions of Azeroth as their playing pieces.]]
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].zones = {"Voidstorm"}
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["decimus_midnight"].timeline = IMAGOdb.timelines.DECIMUS

IMAGOdb.npcs.CAT_NEUTRAL["king_mrgl-mrgl_midnight"].name = "King Mrgl-Mrgl"
IMAGOdb.npcs.CAT_NEUTRAL["king_mrgl-mrgl_midnight"].aliases = {}
IMAGOdb.npcs.CAT_NEUTRAL["king_mrgl-mrgl_midnight"].race = "Murloc"
IMAGOdb.npcs.CAT_NEUTRAL["king_mrgl-mrgl_midnight"].lore = "Behind King Mrgl-Mrgl's grand murloc facade lies a simple night elf researcher. Originally a part of a druidic research group, King Mrgl-Mrgl has grown far beyond his humble beginnings. After disguising himself as a murloc to observe their populations in Northrend, Mrgl-Mrgl was revered by the creatures and chosen as their king. Though originally reluctant, he accepted the role and never looked back. Ever since, King Mrgl-Mrgl has been found aiding the murlocs of Azeroth and protecting them from outside threats."
IMAGOdb.npcs.CAT_NEUTRAL["king_mrgl-mrgl_midnight"].zones = {"Zul'Aman"}
IMAGOdb.npcs.CAT_NEUTRAL["king_mrgl-mrgl_midnight"].source = "austin"
IMAGOdb.npcs.CAT_NEUTRAL["king_mrgl-mrgl_midnight"].timeline = IMAGOdb.timelines.KING_MRGL_MRGL

-- MONTE GAZLOWE --
IMAGOdb.npcs.CAT_NEUTRAL["monte_gazlowe_midnight"].name = "Monte Gazlowe"
IMAGOdb.npcs.CAT_NEUTRAL["monte_gazlowe_midnight"].aliases = {"Monte Gazlowe", "Monte", "Gazlowe"}
IMAGOdb.npcs.CAT_NEUTRAL["monte_gazlowe_midnight"].race = "Goblin"
IMAGOdb.npcs.CAT_NEUTRAL["monte_gazlowe_midnight"].lore = [[The architect of Orgrimmar and Trade Prince of the Bilgewater Cartel is one of the Horde's most important members, even if his influence is mostly felt in the background. He isn't a fighter, doesn't consider himself a hero and is seen by most as nothing but another greedy goblin. 

That is not what lies below the surface though, and the people that know him beyond shallow appearances know that this goblin has a great heart under all his snark. 

His reforms have given the exploited workers of his cartel security and rights for the first time in goblin culture. He has lent monetary support to a lot of his Horde allies out of loyalty and without bartering for much in return. He was instrumental in bringing revolutionary change to the Undermine, even when he was planning on not getting involved at first.

He has formed a friendship with Orweyna and the two have begun to show each other their cultures.]]
IMAGOdb.npcs.CAT_NEUTRAL["monte_gazlowe_midnight"].zones = {"Harandar", "The Den"}
IMAGOdb.npcs.CAT_NEUTRAL["monte_gazlowe_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["monte_gazlowe_midnight"].timeline = IMAGOdb.timelines.MONTE_GAZLOWE

IMAGOdb.npcs.CAT_NEUTRAL["valeera_sanguinar_midnight"].name = "Valeera Sanguinar"
IMAGOdb.npcs.CAT_NEUTRAL["valeera_sanguinar_midnight"].aliases = {"Valeera"}
IMAGOdb.npcs.CAT_NEUTRAL["valeera_sanguinar_midnight"].race = "Blood Elf"
IMAGOdb.npcs.CAT_NEUTRAL["valeera_sanguinar_midnight"].lore = [[Valeera Sanguinar owes allegiance to no faction and no leader. The young blood elf woman was orphaned at a young age and lived on the streets, thieving to survive. Whether it was the Scourge, mana addiction or enslavement – somehow Valeera made it through. She became slow to trust anybody, felt betrayed by the world, and became a reckless assassin.

When she finally made true friends with Varian Wrynn and Broll Bearmantle, she took her first steps back into a healthier way of life. Owing her life to Varian she served him as a bodyguard without any obligation to the Alliance. After his death she coninued to serve his son, Anduin and Stormwind became her second home.

Now, as a neutral friend to both factions, she aids the Champions of Azeroth in vanquishing foes that plot against Silvermoon from within the darkest depths of Quel'Thalas and beyond.]]

IMAGOdb.npcs.CAT_NEUTRAL["valeera_sanguinar_midnight"].zones = {"Eversong Woods", "Parhelion Plaza", "Silvermoon City", "Zul'Aman", "Sunkiller Sanctum", "Atal'Aman", "Collegiate Calamity", "Shadowguard Point", "The Darkway", "The Grudge Pit", "The Gulf of Memory", "The Shadow Enclave", "Twilight Crypts"}
IMAGOdb.npcs.CAT_NEUTRAL["valeera_sanguinar_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["valeera_sanguinar_midnight"].timeline = IMAGOdb.timelines.VALEERA_SANGUINAR

-- FREYA --
IMAGOdb.npcs.CAT_NEUTRAL["freya_midnight"].name = "Freya"
IMAGOdb.npcs.CAT_NEUTRAL["freya_midnight"].aliases = {}
IMAGOdb.npcs.CAT_NEUTRAL["freya_midnight"].race = "Titanic watcher"
IMAGOdb.npcs.CAT_NEUTRAL["freya_midnight"].lore = [[Freya has reliably done the mighty titan Eonar's bidding on Azeroth as her keeper since her creation. She is credited in the records of the Titans of creating most life on the planet, including the Wild Gods and loa, and to have been the one that created the Emerald Dream. Other sources may say differently, and describe the Dream as something that has always existed, and that life has had a place in the world long before the Titans came – but it is undeniable that Freya's influence can be felt on Azeroth wherever nature sprouts.

With the Titans' defeat at Sargeras' hand, Freya has become somewhat stagnant, just like most of the other keepers have.]]
IMAGOdb.npcs.CAT_NEUTRAL["freya_midnight"].zones = {"Harandar"}
IMAGOdb.npcs.CAT_NEUTRAL["freya_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["freya_midnight"].timeline = IMAGOdb.timelines.FREYA

IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].name = "Eitrigg"
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].aliases = {}
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].race = "Orc"
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].lore = "A veteran of countless battles, he is one of the most important orcs in the history of the Horde, one of the few who remember the dark ages of the past when countless horrors were committed against the innocent. He fought for the Old Horde on Draenor and in the New Horde to this day on Azeroth, forging a bond with Tirion Fordring, a human, after years of war between the two races. He served as an advisor to Thrall and Garrosh as Warchiefs and rose up when necessary against the latter and Sylvanas Windrunner. He was eventually admitted into the Sons of Lothar as a symbol that honor can come from anyone."
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].zones = {"Burning Steppes", "Arcantina",  "Arathi Highlands", "Silvermoon City"}
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].source = "Karstan"
IMAGOdb.npcs.CAT_NEUTRAL["eitrigg_midnight"].timeline = IMAGOdb.timelines.EITRIGG

-- KURDRAN WILDHAMMER --
IMAGOdb.npcs.CAT_NEUTRAL["kurdran_wildhammer_midnight"].name = "Kurdran Wildhammer"
IMAGOdb.npcs.CAT_NEUTRAL["kurdran_wildhammer_midnight"].aliases = {"Kurdran"}
IMAGOdb.npcs.CAT_NEUTRAL["kurdran_wildhammer_midnight"].race = "Dwarf"
IMAGOdb.npcs.CAT_NEUTRAL["kurdran_wildhammer_midnight"].lore = [[A thane of the Wildhammer clan and skilled gryphon rider, Kurdran was one of the first dwarves to take up arms against the invading orcs in the Second War. He joined the Alliance of Lordaeron and eventually followed general Turalyon beyond the Dark Portal into Outland. He forged a bond of true friendship with the Sons of Lothar.

He returned to Azeroth after surviving two decades on the broken orcish world. Kurdran tried his hand at politics for a time - briefly acting as representative of the Wildhammer clan in Ironforge – before settling down for a time.

Now, reunited with his friends of old, Kurdran is ready once again to fight for the good of Azeroth.]]
IMAGOdb.npcs.CAT_NEUTRAL["kurdran_wildhammer_midnight"].zones = {"Burning Steppes", "Arcantina", "Silvermoon City"}
IMAGOdb.npcs.CAT_NEUTRAL["kurdran_wildhammer_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["kurdran_wildhammer_midnight"].timeline = IMAGOdb.timelines.KURDRAN_WILDHAMMER

-- LIRATH WINDRUNNER --
IMAGOdb.npcs.CAT_NEUTRAL["lirath_windrunner_midnight"].name = "Lirath Windrunner"
IMAGOdb.npcs.CAT_NEUTRAL["lirath_windrunner_midnight"].aliases = {"Lirath"}
IMAGOdb.npcs.CAT_NEUTRAL["lirath_windrunner_midnight"].race = "High elf"
IMAGOdb.npcs.CAT_NEUTRAL["lirath_windrunner_midnight"].lore = [[The youngest of the four, and only brother among the Windrunner siblings. Lirath was a brilliant singer who made a name for himself performing at Lord Saltheril's court, and was eventually named Royal Musician by Kael'thas Sunstrider.

After the death of their parents, Lirath demanded his sisters train him as a ranger. Lirath was killed while defending Windrunner Village from orcs during the burning of Quel'thalas.]]
IMAGOdb.npcs.CAT_NEUTRAL["lirath_windrunner_midnight"].zones = {"Windrunner Spire"}
IMAGOdb.npcs.CAT_NEUTRAL["lirath_windrunner_midnight"].source = "Travanoid"
IMAGOdb.npcs.CAT_NEUTRAL["lirath_windrunner_midnight"].timeline = IMAGOdb.timelines.LIRATH_WINDRUNNER

-- LORD MAXWELL TYROSUS --
IMAGOdb.npcs.CAT_NEUTRAL["lord_maxwell_tyrosus_midnight"].name = "Lord Maxwell Tyrosus"
IMAGOdb.npcs.CAT_NEUTRAL["lord_maxwell_tyrosus_midnight"].race = "Human"
IMAGOdb.npcs.CAT_NEUTRAL["lord_maxwell_tyrosus_midnight"].lore = [[Ever since the Scourge ravaged the Eastern Kingdoms, Maxwell Tyrosus has made it his calling to fight the undead and protect the innocent. He has not only become the leader of the Argent Dawn, but also the Hand of the Highlord of the Order of the Silver Hand. He may not have a flashy title or performed war-winning heroics like his fellow paladins such as Turalyon or Uther the Lightbringer – yet Tyrosus has become an invaluable asset in keeping the paladin orders disciplined and battle-ready.

Even though he has lived in service of the Light for decades, Tyrosus has not been summoned by the Sunwell. Not letting himself be deterred by broken pride or doubt, he now faces new threats outside of Silvermoon without hesitation.]]
IMAGOdb.npcs.CAT_NEUTRAL["lord_maxwell_tyrosus_midnight"].zones = {"Eastern Plaguelands"}
IMAGOdb.npcs.CAT_NEUTRAL["lord_maxwell_tyrosus_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["lord_maxwell_tyrosus_midnight"].timeline = IMAGOdb.timelines.LORD_MAXWELL_TYROSUS

-- MAIEV SHADOWSONG --
IMAGOdb.npcs.CAT_NEUTRAL["maiev_shadowsong_midnight"].name = "Maiev Shadowsong"
IMAGOdb.npcs.CAT_NEUTRAL["maiev_shadowsong_midnight"].race = "Night elf"
IMAGOdb.npcs.CAT_NEUTRAL["maiev_shadowsong_midnight"].lore = [[Illidan Stormrage has for the longest part of her life been the focus of Maiev's ire. As leader of the Watchers, she was tasked with ensuring the Betrayer never left his prison and for ten thousand years she succeeded. Her own isolation during her long vigil made her become obsessed with her prisoner and when he was freed to combat the Burning Legion, Maiev became restless. 

She needed time to forge a new purpose for herself in the world and her quick temper and sometimes radical disposition often made her clash with her fellow night elves. After years of adjustment and letting bygones be bygones on both sides, Maiev now once more serves her people under Shandris Feathermoon's leadership.]]
IMAGOdb.npcs.CAT_NEUTRAL["maiev_shadowsong_midnight"].zones = {"Amirdrassil"}
IMAGOdb.npcs.CAT_NEUTRAL["maiev_shadowsong_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["maiev_shadowsong_midnight"].timeline = IMAGOdb.timelines.MAIEV_SHADOWSONG

-- BRANN BRONZEBEARD --
IMAGOdb.npcs.CAT_NEUTRAL["brann_bronzebeard_midnight"].name = "Brann Bronzebeard"
IMAGOdb.npcs.CAT_NEUTRAL["brann_bronzebeard_midnight"].race = "Dwarf"
IMAGOdb.npcs.CAT_NEUTRAL["brann_bronzebeard_midnight"].lore = [[Everyone who considers themselves an archaeologist or historian has heard of Brann Bronzebeard. The youngest of the three Bronzebeard brothers has no claim to, or interest in, the High Seat of Ironforge and instead carved out a reputation as one of Azeroth's most famous explorers. The first complete maps of Kalimdor and the Eastern Kingdoms were made by his hand, showing that he even ventured deep into enemy territory to make them as precise as possible. 

Whenever a new continent or ruin is discovered – especially if it's of Titan origin – Brann can be found at the forefront, wherever the action is.]]
IMAGOdb.npcs.CAT_NEUTRAL["brann_bronzebeard_midnight"].zones = {"Silvermoon City"}
IMAGOdb.npcs.CAT_NEUTRAL["brann_bronzebeard_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["brann_bronzebeard_midnight"].timeline = IMAGOdb.timelines.BRANN_BRONZEBEARD

-- SORIDORMI --
IMAGOdb.npcs.CAT_NEUTRAL["soridormi_midnight"].name = "Soridormi"
IMAGOdb.npcs.CAT_NEUTRAL["soridormi_midnight"].race = "Bronze Dragon"
IMAGOdb.npcs.CAT_NEUTRAL["soridormi_midnight"].lore = [[As a bronze dragon, Soridormi's chief directive is to protect and maintain the Titans' one true timeline. She is the prime consort of the Timeless One, Nozdormu, and thus in charge of many matters concerning the bronze flight as a whole. Wherever history teeters on the brink of unraveling or dragonkind stands in need of protection, Soridormi is never far behind.]]
IMAGOdb.npcs.CAT_NEUTRAL["soridormi_midnight"].zones = {"Silvermoon City"}
IMAGOdb.npcs.CAT_NEUTRAL["soridormi_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["soridormi_midnight"].timeline = IMAGOdb.timelines.SORIDORMI

-- QUEEN TALANJI --
IMAGOdb.npcs.CAT_NEUTRAL["queen_talanji_midnight"].name = "Queen Talanji"
IMAGOdb.npcs.CAT_NEUTRAL["queen_talanji_midnight"].race = "Zandalari Troll"
IMAGOdb.npcs.CAT_NEUTRAL["queen_talanji_midnight"].lore = [[Thousands of years ago, the trolls ruled over Azeroth. Now, only one of their great empires remains: Zandalar, to which all other troll tribes look in respect. Talanji reigns as queen of the Zandalari and although she is young, her authority and royal lineage are beyond dispute.  Temperamental and headstrong, and with the power of the Loa of Death on her side, she is a force to be reckoned with.

After she came to power when Alliance adventurers murdered her father, King Rastakhan, Talanji allied with the Horde, swearing vengeance. While she honors the truce between the factions, she doesn't hide her lingering disdain for the Alliance and makes it quite clear that if war was ever to break out again, she would not argue for peace long.]]
IMAGOdb.npcs.CAT_NEUTRAL["queen_talanji_midnight"].zones = {"The Den"}
IMAGOdb.npcs.CAT_NEUTRAL["queen_talanji_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["queen_talanji_midnight"].timeline = IMAGOdb.timelines.QUEEN_TALANJI

-- ROKHAN --
IMAGOdb.npcs.CAT_NEUTRAL["rokhan_midnight"].name = "Rokhan"
IMAGOdb.npcs.CAT_NEUTRAL["rokhan_midnight"].race = "Jungle troll"
IMAGOdb.npcs.CAT_NEUTRAL["rokhan_midnight"].lore = [[Rokhan has been a proud and loyal member of the Darkspear Tribe and the Horde since the Third War. Through exceptional skill as a shadow hunter and tracker, he worked his way up the ranks, and when Warchief Vol'jin fell to the Burning Legion, Rokhan was elected to replace him as chieftain of the Darkspear. 

Since then, he has been instrumental in bringing the Zandalari into the ranks of the Horde, remaining friends with Queen Talanji to this day, and in bringing the lost Loa of the Darkspear back into their society. Rokhan has fought, and always will fight, for what is best for his people.]]
IMAGOdb.npcs.CAT_NEUTRAL["rokhan_midnight"].zones = {"The Den"}
IMAGOdb.npcs.CAT_NEUTRAL["rokhan_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["rokhan_midnight"].timeline = IMAGOdb.timelines.ROKHAN

-- ZEKHAN --
IMAGOdb.npcs.CAT_NEUTRAL["zekhan_midnight"].name = "Zekhan"
IMAGOdb.npcs.CAT_NEUTRAL["zekhan_midnight"].race = "Jungle troll"
IMAGOdb.npcs.CAT_NEUTRAL["zekhan_midnight"].lore = [[This young, honest, and idealistic jungle troll became a key player during the Fourth War as Varok Saurfang's first supporter and closest confidant. After Saurfang's sacrifice, Zekhan swore to carry on the legacy of honor his fatherly friend left behind. He has been made ambassador of the Horde for his heroics and has earned the unconditional trust of various leaders of the Horde, Queen Talanji, Rokhan and Thrall chief among them. 

Now, the young shaman has been invited to Harandar, and remains optimistic for whatever Hagar's revelation might bring for the future.]]
IMAGOdb.npcs.CAT_NEUTRAL["zekhan_midnight"].zones = {"The Den"}
IMAGOdb.npcs.CAT_NEUTRAL["zekhan_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["zekhan_midnight"].timeline = IMAGOdb.timelines.ZEKHAN

IMAGOdb.npcs.CAT_NEUTRAL["commander_jarod_shadowsong_midnight"].name = "Commander Jarod Shadowsong"
IMAGOdb.npcs.CAT_NEUTRAL["commander_jarod_shadowsong_midnight"].race = "Night elf"
IMAGOdb.npcs.CAT_NEUTRAL["commander_jarod_shadowsong_midnight"].lore = [[Jarod Shadowsong was once called “the Hope of the Elves” during the War of the Ancients. As one superior after another fell in battle, due to his sheer skill and determination, he could have become the leader of the Kaldorei after the war was won. Never one to crave power or seek that kind of responsibility, he left his people and lived in self-exile with his wife, Shalasyr, for ten thousand years.

He rejoined night elven society when Shalasyr passed away and repaired his relationship with his sister, Maiev. He has since served as an army commander again during the Fourth War and the war against Fyrakk in the Emerald Dream.]]
IMAGOdb.npcs.CAT_NEUTRAL["commander_jarod_shadowsong_midnight"].zones = {"Amirdrassil", "Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_NEUTRAL["commander_jarod_shadowsong_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["commander_jarod_shadowsong_midnight"].timeline = {
    {
        era = "Ancient",
        text = [[Fought under Kur'talos Ravencrest and then Desdel Stareye during the War of the Ancients. Rose through the ranks and became the military leader of the Kaldorei resistance, with even Malfurion and Tyrande deferring to him. Burdened by survivor's guilt and disillusioned by how the Kaldorei moved on as a people, he left society with his wife Shalasyr after the war was won.]],
    },
    {
        era = "WC3",
        text = [[Heard rumors that the night elves, himself and his wife included, had become mortal.]],
    },
    {
        era = "Pre-Cata",
        text = [[After living together for ten thousand years, Shalasyr fell ill and passed away. Distraught, Jarod rejoined the night elves in Darnassus and reconnected with his sister Maiev and former war companions. Uncovered Maiev's killing spree of Highborne and Worgen victims, and drove her off into exile.]],
    },
    {
        era = "Cata",
        text = [[Fought Ragnaros and the Twilight's Hammer on Mount Hyjal. Was captured by the cult and saved by an Adventurer. Commanded the night elven military and once more fought alongside dragons and Wild Gods.]],
    },
    {
        era = "Legion",
        text = [[Freed Maiev from Black Rook Hold and fought alongside her to defeat the ghost of Lord Desdel Stareye. Later, together with Cenarius, led the defense of Black Rook Hold when it came under assault from the Burning Legion.]],
    },
    {
        era = "BfA",
        text = [[Fought under Maiev during the Battle of Darkshore against the Horde.]],
    },
    {
        era = "DF",
        text = [[Joined the united forces of Azeroth in the Emerald Dream to defeat Fyrakk the Blazing. Helped establish Bel'ameth and chose to remain there.]],
    },
    {
        era = "Midnight",
        text = [[Fought on the Isle of Quel'Danas against the Devouring Host.]],
    }
}

-- BELATH_DAWNBLADE --
IMAGOdb.npcs.CAT_NEUTRAL["belath_dawnblade_midnight"].name = "Belath Dawnblade"
IMAGOdb.npcs.CAT_NEUTRAL["belath_dawnblade_midnight"].race = "Blood elf"
IMAGOdb.npcs.CAT_NEUTRAL["belath_dawnblade_midnight"].lore = [[The Illidari are mostly known as reckless but efficient hunters of demons. Belath shares their tenacity, but his strength lies in a stealthy and creative approach to combat. A blood elven scout by trade, he stands out as a calm and capable mind who has risen in the ranks through results alone. 

Just because the Legion has been defeated doesn't mean that Belath now rests on his laurels. He has returned to Silvermoon to eradicate the Void besieging it – and any traces of Fel magic left.]]
IMAGOdb.npcs.CAT_NEUTRAL["belath_dawnblade_midnight"].zones = {"Silvermoon City", "Murder Row", "Val", "Naigtal"}
IMAGOdb.npcs.CAT_NEUTRAL["belath_dawnblade_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["belath_dawnblade_midnight"].timeline = {
    {
        era = "TBC",
        text = [[Participated in the invasion of Mardum and briefly got captured by demons of the Burning Legion. Was later imprisoned alongside his fellow Illidari by Maiev Shadowsong.]],
    },
    {
        era = "Legion",
        text = [[After being freed to fight in the Third Invasion of the Burning Legion, he worked alongside the Wardens to track down any other demons that had escaped from the Vault of the Wardens. He coordinated scouting missions to the Black Temple, Stormheim, and Niskara and fought as the Slayer's Champion.]],
    },
    {
        era = "Midnight",
        text = [[Stopped an illegal operation in Murder Row that supplied the frightened citizens of Silvermoon with Fel Magic. After Xal'atath's disappearance through the Darkwell, Belath tracked down the new ethereal and domanaar leaders of the Devouring Host to the formerly Legion-occupied worlds of Val and Naigtal. Joined Decimus' and Maella's strike teams on both worlds.]],
    }
}

-- WARDRUID LOTI --
IMAGOdb.npcs.CAT_NEUTRAL["wardruid_loti_midnight"].name = "Wardruid Loti"
IMAGOdb.npcs.CAT_NEUTRAL["wardruid_loti_midnight"].race = "Zandalari troll"
IMAGOdb.npcs.CAT_NEUTRAL["wardruid_loti_midnight"].lore = [[Under King Rastakhan, four of the six members of the Zanchuli Council turned traitors. Loti was not among them and faithfully served the king until his death. Now she advises his daughter, Queen Talanji, with equal loyalty. 

Loti is responsible for a resurgence of druidism in Zandalar, and as the High Priestess of Gonk, the Great Hunter, she has inspired the young generations of warriors, hunters and druids of her homeland. Her tenacity in battle is second only to her loa himself.]]
IMAGOdb.npcs.CAT_NEUTRAL["wardruid_loti_midnight"].zones = {"The Den"}
IMAGOdb.npcs.CAT_NEUTRAL["wardruid_loti_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_NEUTRAL["wardruid_loti_midnight"].timeline = {
    {
        era = "Pre-BfA",
        text = [[Earned her place in the Zanchuli Council as one of its younger members through the overwhelming support from Zandalar's hunters and warriors. Druidism saw a rise in popularity in the empire after she was appointed.]],
    },
    {
        era = "BfA",
        text = [[Investigated the use of illegal blood magic in Dazar'alor and frequently empowered the Horde Champion with Gonk's power. Remained loyal to Rastakhan when Yazma and Zul betrayed the crown and helped defend the kingdom against Mythrax the Unraveler. Fought against the Alliance in the Battle of Dazar'alor. Attended Queen Talanji's coronation and swore loyalty to her.]],
    },
    {
        era = "DF",
        text = [[Met with Zen'tabra of the Darkspear Tribe in the Ohn'ahran Plains and aided the green dragonflight to reclaim the portal on the Ancient Bough from the Primalists.]],
    },
    {
        era = "Midnight",
        text = [[Accompanied Queen Talanji to Harandar.]],
    }
}

-- CAT_EBON_BLADE
IMAGOdb.npcs.CAT_EBON_BLADE["high_inquisitor_whitemane_midnight"].name = "High Inquisitor Whitemane"
IMAGOdb.npcs.CAT_EBON_BLADE["high_inquisitor_whitemane_midnight"].aliases = {"Sally Whitemane", "Whitemane"}
IMAGOdb.npcs.CAT_EBON_BLADE["high_inquisitor_whitemane_midnight"].race = "Human"
IMAGOdb.npcs.CAT_EBON_BLADE["high_inquisitor_whitemane_midnight"].lore = [[Following the death of her family at the hands of the Scourge in Lordaeron, Sally Whitemane had one focus - destroying the undead in their entirety. As a zealous priestess of the Light fueled by guilt and rage towards the undead, she was welcomed into the Scarlet Crusade, and very quickly rose through the ranks to the position of High Inquisitor. After taking control of the organization following what was believed to be her demise at the Scarlet Monastery years prior, she was finally slain by the forsaken assassin Lillian Voss and a band of adventurers.

Now resurrected as a member of the Four Horsemen, Sally has recovered from her immense hatred, but remains passionate and devoted, now to the defense of Azeroth with her fellow Death Knights of the Ebon Blade.]]
IMAGOdb.npcs.CAT_EBON_BLADE["high_inquisitor_whitemane_midnight"].zones = {"Eastern Plaguelands"}
IMAGOdb.npcs.CAT_EBON_BLADE["high_inquisitor_whitemane_midnight"].source = "Nebb"
IMAGOdb.npcs.CAT_EBON_BLADE["high_inquisitor_whitemane_midnight"].timeline = IMAGOdb.timelines.HIGH_INQUISITOR_WHITEMANE

IMAGOdb.npcs.CAT_EBON_BLADE["darion_mograine_midnight"].name = "Highlord Darion Mograine"
IMAGOdb.npcs.CAT_EBON_BLADE["darion_mograine_midnight"].aliases = {"Darion Mograine", "Darion"}
IMAGOdb.npcs.CAT_EBON_BLADE["darion_mograine_midnight"].race = "Human"
IMAGOdb.npcs.CAT_EBON_BLADE["darion_mograine_midnight"].lore =
[[
Darion Mograine was a paladin of the Argent Dawn who, after sacrificing his life to save the soul of his father, was resurrected as a Death Knight to serve as one of the Lich King's most powerful commanders. Breaking free from the Lich King's control at the Battle for Light's Hope Chapel, he founded the Ebon Blade, a band of Death Knights committed to protecting Azeroth from any threats that come her way.

Now leading the Four Horsemen, Darion defends the home of the Argent Crusade from the Scourge whilst they assist Azeroth's champion with the destruction of the Devouring Host.]]
IMAGOdb.npcs.CAT_EBON_BLADE["darion_mograine_midnight"].zones = {"Eastern Plaguelands"}
IMAGOdb.npcs.CAT_EBON_BLADE["darion_mograine_midnight"].source = "Nebb"
IMAGOdb.npcs.CAT_EBON_BLADE["darion_mograine_midnight"].timeline = IMAGOdb.timelines.DARION_MOGRAINE

IMAGOdb.npcs.CAT_EBON_BLADE["thassarian_midnight"].name = "Thassarian"
IMAGOdb.npcs.CAT_EBON_BLADE["thassarian_midnight"].aliases = {}
IMAGOdb.npcs.CAT_EBON_BLADE["thassarian_midnight"].race = "Human"
IMAGOdb.npcs.CAT_EBON_BLADE["thassarian_midnight"].lore =
[[As a young man, Thassarian joined the Lordaeron army hoping to follow in his father's footsteps, and followed Prince Arthas on his expedition to Northrend. It was there he was slain and reanimated as a death knight. During his time under the Lich King's control, he committed many atrocities, even killing his mother. After being freed from the Lich King's control, he joined the Knights of the Ebon Blade and became the first death knight to serve the Alliance, showing unwavering loyalty to humanity once more. 

Despite the faction divide, Thassarian maintains a powerful, complicated brotherhood with the Horde death knight Koltira Deathweaver, a bond forged in death that heavily influences his path.]]
IMAGOdb.npcs.CAT_EBON_BLADE["thassarian_midnight"].zones = {"Eastern Plaguelands"}
IMAGOdb.npcs.CAT_EBON_BLADE["thassarian_midnight"].source = "druidian"
IMAGOdb.npcs.CAT_EBON_BLADE["thassarian_midnight"].timeline = IMAGOdb.timelines.THASSARIAN

IMAGOdb.npcs.CAT_EBON_BLADE["nazgrim_midnight"].name = "Nazgrim"
IMAGOdb.npcs.CAT_EBON_BLADE["nazgrim_midnight"].aliases = {}
IMAGOdb.npcs.CAT_EBON_BLADE["nazgrim_midnight"].race = "Orc"
IMAGOdb.npcs.CAT_EBON_BLADE["nazgrim_midnight"].lore = [[Honor, loyalty, courage - there is nothing more important to orcs. For Nazgrim, these were not merely mottos, but the very meaning of life.

Starting as a lowly sergeant in Garrosh Hellscream's army, Nazgrim quickly rose to the rank of general through his achievements across Azeroth and became one of the closest allies of Warchief Hellscream.

When the Horde rebelled against Hellscream and the moment came to choose between duty and morality, Nazgrim chose the former with grim determination, standing firm against the invaders and ultimately giving his life in service to his Warchief.

However, his story did not end there, as he was risen by the Knights of the Ebon Blade as the first of the new Four Horsemen. Upon learning of the third invasion of the Burning Legion, he accepted his new role without hesitation and remained steadfast in his service to his people.]]
IMAGOdb.npcs.CAT_EBON_BLADE["nazgrim_midnight"].zones = {"Eastern Plaguelands", "The Dreamrift", "The Voidspire"}
IMAGOdb.npcs.CAT_EBON_BLADE["nazgrim_midnight"].source = "Metrus"
IMAGOdb.npcs.CAT_EBON_BLADE["nazgrim_midnight"].timeline = IMAGOdb.timelines.NAZGRIM

IMAGOdb.npcs.CAT_EBON_BLADE["koltira_deathweaver_midnight"].name = "Koltira Deathweaver"
IMAGOdb.npcs.CAT_EBON_BLADE["koltira_deathweaver_midnight"].aliases = {"Koltira"}
IMAGOdb.npcs.CAT_EBON_BLADE["koltira_deathweaver_midnight"].race = "Darkfallen Blood Elf"
IMAGOdb.npcs.CAT_EBON_BLADE["koltira_deathweaver_midnight"].lore = [[Koltira fought and died for Silvermoon when Arthas and the Scourge marched through her gates. Death was not the end for him though as he was promptly resurrected as a Death Knight. 

Under Arthas' control, he was forced to kill for the very army that destroyed everything he had once known and loved. He developed a true bond of friendship with Thassarian, the man who killed him, despite their gruesome circumstances.  Both of them were freed from the Lich King's mind control and chose to fight for the newly formed Ebon Blade and vowed to keep all of Azeroth safe from the undead. Koltira joined the Horde and acted as an emissary for his fellow Death Knights.

Though they have found themselves on the opposite sides of the faction wars at times, Koltira Deathweaver and Thassarian remain close friends.]]
IMAGOdb.npcs.CAT_EBON_BLADE["koltira_deathweaver_midnight"].zones = {"Eastern Plaguelands"}
IMAGOdb.npcs.CAT_EBON_BLADE["koltira_deathweaver_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_EBON_BLADE["koltira_deathweaver_midnight"].timeline = IMAGOdb.timelines.KOLTIRA_DEATHWEAVER

IMAGOdb.npcs.CAT_EBON_BLADE["thoras_trollbane_midnight"].name = "Thoras Trollbane"
IMAGOdb.npcs.CAT_EBON_BLADE["thoras_trollbane_midnight"].aliases = {"Thoras",}
IMAGOdb.npcs.CAT_EBON_BLADE["thoras_trollbane_midnight"].race = "Human"
IMAGOdb.npcs.CAT_EBON_BLADE["thoras_trollbane_midnight"].lore = [[Loved by his people and feared by his enemies, Thoras Trollbane was the warrior king of Stromgarde, and a founding member of the Alliance of Lordaeron.

After the defeat of the orcs in the Second War, Thoras disagreed with the policy of keeping the surviving orcs in internment camps, openly calling for them to be executed. When Lordaeron refused, Trollbane bitterly withdrew his support from the Alliance.

At some point after the death of King Terenas Menethil, Thoras was murdered by his son Galen.

During the Burning Legion's third invasion, the Knights of the Ebon Blade raised Thoras as a member of the Four Horsemen. Believing that he had failed as a father and as a king, Thoras joined them in order to preserve peace in Azeroth.]]
IMAGOdb.npcs.CAT_EBON_BLADE["thoras_trollbane_midnight"].zones = {"The Dreamrift", "The Voidspire", "Eastern Plaguelands"}
IMAGOdb.npcs.CAT_EBON_BLADE["thoras_trollbane_midnight"].source = "Travanoid"
IMAGOdb.npcs.CAT_EBON_BLADE["thoras_trollbane_midnight"].timeline = IMAGOdb.timelines.THORAS_TROLLBANE

-- CAT_VOID
IMAGOdb.npcs.CAT_VOID["nexuskoenig_salhadaar_midnight"].name = "Nexus-King Salhadaar"
IMAGOdb.npcs.CAT_VOID["nexuskoenig_salhadaar_midnight"].aliases = {"Nexus-King", "Salhadaar"}
IMAGOdb.npcs.CAT_VOID["nexuskoenig_salhadaar_midnight"].race = "Void Ethereal"
IMAGOdb.npcs.CAT_VOID["nexuskoenig_salhadaar_midnight"].lore = [[For a long time, Nexus-King Salhadaar has known only desperation and suffering. Thousands of years ago, he ruled the people of the planet K'aresh before it was devoured by the Void.

Losing one's world and one's physical body is enough to turn the strongest soul to madness – and Salhadaar was no exeption. He led his people, now called the Ethereals, into the service of Dimensius the All-Devouring, the very void lord that had taken all he had known.

After being defeated by the Champions of Azeroth, Salhadaar was conscripted by Xal'atath and forced to obey yet another being of the Void. Unwilling but without hope for a way out of this bargain, the Nexus-King and his Shadowguard Ethereals once again oppose the united forces of Azeroth.]]
IMAGOdb.npcs.CAT_VOID["nexuskoenig_salhadaar_midnight"].zones = {"The Voidspire", "Voidstorm"}
IMAGOdb.npcs.CAT_VOID["nexuskoenig_salhadaar_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_VOID["nexuskoenig_salhadaar_midnight"].timeline = IMAGOdb.timelines.NEXUSKOENIG_SALHADAAR

IMAGOdb.npcs.CAT_VOID["l_ura_midnight"].name = "L'ura"
IMAGOdb.npcs.CAT_VOID["l_ura_midnight"].aliases = {}
IMAGOdb.npcs.CAT_VOID["l_ura_midnight"].race = "Naaru"
IMAGOdb.npcs.CAT_VOID["l_ura_midnight"].lore = [[The naaru are perhaps the purest expression of the Light throughout the Great Dark Beyond. 

L'ura was once one of these shining beacons of holy energy. It stayed behind on Argus to ensure Velen and his draenei refugees could escape Kil'jaeden's wrath and, after holding out against countless demons, L'ura was overwhelmed by the Burning Legion. 

Imprisoned for millennia, the once bright creature fell into a state of Void. Guided by madness and chaos and wrath, it became a dangerous entity to most and a powerful weapon to others. 

In the Seat of the Triumvirate, Alleria Windrunner eventually confronted the fallen naaru and subdued it, binding its essence within herself. Now the void-touched ranger wields L'ura's power as her own, yet the darkened naaru still endures within her, waiting for the moment it may be unleashed once again.]]
IMAGOdb.npcs.CAT_VOID["l_ura_midnight"].zones = {"Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_VOID["l_ura_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_VOID["l_ura_midnight"].timeline = IMAGOdb.timelines.L_URA

-- MOR_DUUN --
IMAGOdb.npcs.CAT_VOID["mor_duun_midnight"].name = "Mor'duun"
IMAGOdb.npcs.CAT_VOID["mor_duun_midnight"].aliases = {}
IMAGOdb.npcs.CAT_VOID["mor_duun_midnight"].race = "Ogre"
IMAGOdb.npcs.CAT_VOID["mor_duun_midnight"].lore = [[As a powerful ogre mage, Mor'duun led the Twilght's Blade, a cult devoted to Xal'atath. After his devotion drew her attention, she granted Mor'duun the power of the Void, renewing the cult's fervor. 

Mor'duun personally led the Twilight's Blade's invasion of Zul'Aman, leaving Atal'Aman in ruins and commanding his forces from the Broken Throne.]]
IMAGOdb.npcs.CAT_VOID["mor_duun_midnight"].zones = {"Zul'Aman"}
IMAGOdb.npcs.CAT_VOID["mor_duun_midnight"].source = "Travanoid"
IMAGOdb.npcs.CAT_VOID["mor_duun_midnight"].timeline = IMAGOdb.timelines.MOR_DUUN

-- XAL'ATATH --
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].name = "Xal'atath"
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].aliases = {}
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].race = "Unknown"
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].lore = [[Her smile is a threat, her whispers are warnings, and her promises are lies. The Harbinger of the Void has manipulated the people of Azeroth for millennia, and as easily as she elevated her allies to great power, she abandoned them to their doom.

For the longest time, she was trapped within the Blade of the Black Empire, a punishment imposed by the Old Gods after she opposed them.

With the help of the Champions of Azeroth, she is now free once more.

Xal'atath seeks the world-soul, and with the Dark Heart empowered, she assaults the Sunwell in an attempt to reach it. It remains a mystery why she pursues it, and even her origins are shrouded in ambiguity. All that is certain is that she must be stopped at all costs.

The fate of the universe may depend on the Champions of Azeroth.]]
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].zones = {"The Voidspire", "Isle of Quel'Danas"}
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_VOID["xal_atath_midnight"].timeline = IMAGOdb.timelines.XAL_ATATH


-- CAT_AMANI
IMAGOdb.npcs.CAT_AMANI["zaljarra_midnight"].name = "Zul'jarra"
IMAGOdb.npcs.CAT_AMANI["zaljarra_midnight"].aliases = {}
IMAGOdb.npcs.CAT_AMANI["zaljarra_midnight"].race = "Forest Troll"
IMAGOdb.npcs.CAT_AMANI["zaljarra_midnight"].lore =
[[
The eldest of two siblings, Zul'jarra was raised a warrior. The grand-daughter of the infamous Zul'jin, she was taught the traditional ways to revere the loa and to lead her future clan with honor. The time to lead came sooner than anyone would have expected, for she was merely a child when both her grandfather and her father were slain in the temple city of Zul-Aman. Deemed too young to rule, this left her mother, Zarama, to rule the Amani for decades. When a crippled Zarama eventually tried to pass the title to her daughter, a rival chieftain challenged Zul'jarra's right to rule. Delayed in her return to the duel, Zul'jarra arrived only to watch her mother fall in her place, forcing her to avenge Zarama and claim her birthright in blood.

Now years later, she attempts to finally reconnect the tribes of Zul'Aman to the loa gods, supported, though occasionally opposed, by her brother, Zul'jan.]]
IMAGOdb.npcs.CAT_AMANI["zaljarra_midnight"].zones = {"Atal'Aman", "The Heart of Rage", "Eversong Woods", "Isle of Quel'Danas", "Den of Nalorakk", "Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["zaljarra_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_AMANI["zaljarra_midnight"].timeline = IMAGOdb.timelines.ZALJARRA

-- NALORAKK --
IMAGOdb.npcs.CAT_AMANI["nalorakk_midnight"].name = "Nalorakk"
IMAGOdb.npcs.CAT_AMANI["nalorakk_midnight"].aliases = {"loa of war", "Bear Loa"}
IMAGOdb.npcs.CAT_AMANI["nalorakk_midnight"].race = "Bear (loa)"
IMAGOdb.npcs.CAT_AMANI["nalorakk_midnight"].lore = [[The Unyielding One, The Dreamer, Ironjaw... The Loa of War and of the Earth was revered by many names. The great bear was the primary god of the Revantusk Tribe and granted them strength in battle and prosperity in harvest. Stonemasons laid down offerings for him and he in turn reinforced the walls around them.

Then came Zul'jin and Hex Lord Malacrass and forcefully sealed his sacred essence into their fiercest warriors in a blasphemous battle against the elves of Quel'Thalas. When Zul'jin failed and his army was defeated, Nalorakk, alongside the other loa of Zul'Aman, turned his back on his once-loyal followers.]]
IMAGOdb.npcs.CAT_AMANI["nalorakk_midnight"].zones = {"Den of Nalorakk", "The Heart of Rage", "Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["nalorakk_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_AMANI["nalorakk_midnight"].timeline = IMAGOdb.timelines.NALORAKK

IMAGOdb.npcs.CAT_AMANI["akilzon_midnight"].name = "Akil'zon"
IMAGOdb.npcs.CAT_AMANI["akilzon_midnight"].aliases = {"loa of victory", "Eagle Loa"}
IMAGOdb.npcs.CAT_AMANI["akilzon_midnight"].race = "Eagle (loa)"
IMAGOdb.npcs.CAT_AMANI["akilzon_midnight"].lore = "Akil'zon has long stood behind the Amani trolls as their loa of victory. The great eagle has close ties to the Amani tribe itself, and represents their undying spirit and ferocity. It is said that an Amani berserker blessed by Akil'zon could tear apart an entire elven battalion and return unscathed. Having returned under hash'ey Zul'jarra, Akil'zon fixes her gaze on the Twilight's Blade, talons at the ready."
IMAGOdb.npcs.CAT_AMANI["akilzon_midnight"].zones = {"Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["akilzon_midnight"].source = "austin"
IMAGOdb.npcs.CAT_AMANI["akilzon_midnight"].timeline = IMAGOdb.timelines.AKILZON

IMAGOdb.npcs.CAT_AMANI["janalai_midnight"].name = "Jan'alai"
IMAGOdb.npcs.CAT_AMANI["janalai_midnight"].aliases = {"loa of fire", "Dragonhawk Loa"}
IMAGOdb.npcs.CAT_AMANI["janalai_midnight"].race = "Dragonhawk (loa)"
IMAGOdb.npcs.CAT_AMANI["janalai_midnight"].lore = [[Every year the Shadowpine trolls celebrate Fetna Alai-nazdo - Festival of the Fire Season. It's a tribute to the changing of the season, of summer, and of fire - all domains under the great, fiery wings of Jan'alai. The mighty dragonhawk loa is the patron of life, death, renewal, fire, and magic. She traces the sun across the sky and ignites a fire in Amani hearts. As death draws near, Shadowpine trolls welcome it with open arms, chanting: "Jan'alai must die. We all must die. And she will rise! And we will rise!"]]
IMAGOdb.npcs.CAT_AMANI["janalai_midnight"].zones = {"Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["janalai_midnight"].source = "Metrus & austin"
IMAGOdb.npcs.CAT_AMANI["janalai_midnight"].timeline = IMAGOdb.timelines.JANALAI

IMAGOdb.npcs.CAT_AMANI["halazzi_midnight"].name = "Halazzi"
IMAGOdb.npcs.CAT_AMANI["halazzi_midnight"].aliases = {"the Silver Shadow","Lynx Loa", "Lynx God"}
IMAGOdb.npcs.CAT_AMANI["halazzi_midnight"].race = "Lynx (Loa)"
IMAGOdb.npcs.CAT_AMANI["halazzi_midnight"].lore = [[Loa of the Hunt. The Schemer. The Silver Shadow. Long ear. Forest trolls have many names for him and yet none of them can fully capture the nature of Halazzi. Deep inside the forests of Zul'Aman, Witherbark trolls worship Halazzi and call upon his aid when they hunt. The Lynx Loa hides hunters from their prey and blesses the wilds with mist and rain, keeping them ever bountiful. Although Halazzi is a playful loa, nothing can hide from his ears and eyes - they see the unseen and reveal any lies. Should you find yourself wandering in Amani forests, tread lightly - for Halazzi is never far.]]
IMAGOdb.npcs.CAT_AMANI["halazzi_midnight"].zones = {"Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["halazzi_midnight"].source = "Metrus"
IMAGOdb.npcs.CAT_AMANI["halazzi_midnight"].timeline = IMAGOdb.timelines.HALAZZI

-- Zul'Jan --
IMAGOdb.npcs.CAT_AMANI["zuljan_midnight"].name = "Zul'jan"
IMAGOdb.npcs.CAT_AMANI["zuljan_midnight"].aliases = {}
IMAGOdb.npcs.CAT_AMANI["zuljan_midnight"].race = "Troll"
IMAGOdb.npcs.CAT_AMANI["zuljan_midnight"].lore = [[The impulsive Zul'jan is chief advisor to the current ruler of the Amani tribes – his own sister, Zul'jarra. Unlike her though, Zul'jan distrusts the loa. As he sees it, they had abandoned the trolls in their time of greatest need. As much as he might disagree with his older sister on these matters, he genuinely cares about her and would do his utmost to protect her.

Now, Zul'jan rallies the Amani to become strong by their own merits, not relying on loa or anybody else.]]
IMAGOdb.npcs.CAT_AMANI["zuljan_midnight"].zones = {"Atal'Aman", "Eversong Woods", "Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["zuljan_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_AMANI["zuljan_midnight"].timeline = IMAGOdb.timelines.ZULJAN

-- Loa Speaker Kinduru --
IMAGOdb.npcs.CAT_AMANI["loa_speaker_kinduru_midnight"].name = "Loa Speaker Kinduru"
IMAGOdb.npcs.CAT_AMANI["loa_speaker_kinduru_midnight"].aliases = {"Kinduru"}
IMAGOdb.npcs.CAT_AMANI["loa_speaker_kinduru_midnight"].race = "Forest troll"
IMAGOdb.npcs.CAT_AMANI["loa_speaker_kinduru_midnight"].lore = [[The son of Zul'jin, Kinduru doesn't look back fondly on his father's infamous exploits. Having always been a worshipper of the loa - serving as Speaker of Akil'zon herself - what had transpired during Zul'jin's last battle struck him as an atrocity. The following loss of the loa saddened him deeply.

Now without their gods at their side, Kinduru serves the Amani leader Zul'jarra as advisor. More importantly though, he is her uncle, and he is very fond of both his niece and her brother Zul'jan.

He tried to instill the traditions of loa worship in both of them and, even after all these years, he still holds on to hope that one day their gods will return.]]
IMAGOdb.npcs.CAT_AMANI["loa_speaker_kinduru_midnight"].zones = {"Atal'Aman", "Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["loa_speaker_kinduru_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_AMANI["loa_speaker_kinduru_midnight"].timeline = IMAGOdb.timelines.LOA_SPEAKER_KINDURU

-- FILO --
IMAGOdb.npcs.CAT_AMANI["filo_midnight"].name = "Filo"
IMAGOdb.npcs.CAT_AMANI["filo_midnight"].aliases = {"loa of children", "Kapara Loa"}
IMAGOdb.npcs.CAT_AMANI["filo_midnight"].race = "Kapara (Loa)"
IMAGOdb.npcs.CAT_AMANI["filo_midnight"].lore = [[Worshipped in Zul'Aman as the Loa of Children, Filo never speaks on his own, instead taking the youngest child of each village as his speaker. While gentle toward those he protects, he pursues anyone who dares harm his children with a vow of vengeance.

When a child dies before their parents, Filo will guard their spirit until their parents join them in the afterlife.]]
IMAGOdb.npcs.CAT_AMANI["filo_midnight"].zones = {"Zul'Aman", "Atal'Aman"}
IMAGOdb.npcs.CAT_AMANI["filo_midnight"].source = "Travanoid"
IMAGOdb.npcs.CAT_AMANI["filo_midnight"].timeline = IMAGOdb.timelines.FILO

-- TORUNDO THE GRIZZLED --
IMAGOdb.npcs.CAT_AMANI["torundo_the_grizzled_midnight"].name = "Torundo the Grizzled"
IMAGOdb.npcs.CAT_AMANI["torundo_the_grizzled_midnight"].race = "Forest troll"
IMAGOdb.npcs.CAT_AMANI["torundo_the_grizzled_midnight"].lore = [[When Torundo was but a mere child, his home of Zen'tamani was burned down by the Farstriders of Quel'Thalas, leaving the few survivors helpless and bitter. He fled to Amani'Zar and grew up a formidable warrior loyal to the Amani warlord Zul'jin, who promised his people revenge and glory. Even after Zul'jin's defeat, Torundo remained in service to his bloodline.

Now, he serves Chieftain Zul'jarra as her war advisor, defending Zul'Aman from the Twilight's Blade. While he has mellowed somewhat with age, the sight of a dead enemy still brings a smile to his grizzled face.]]
IMAGOdb.npcs.CAT_AMANI["torundo_the_grizzled_midnight"].zones = {"Zul'Aman", "Atal'Aman", "The Den"}
IMAGOdb.npcs.CAT_AMANI["torundo_the_grizzled_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_AMANI["torundo_the_grizzled_midnight"].timeline = IMAGOdb.timelines.TORUNDO_THE_GRIZZLED

-- SHADRA --
IMAGOdb.npcs.CAT_AMANI["shadra_midnight"].name = "Shadra"
IMAGOdb.npcs.CAT_AMANI["shadra_midnight"].race = "Spider (Loa)"
IMAGOdb.npcs.CAT_AMANI["shadra_midnight"].lore = [[The Venom Queen is a loa worshiped by nearly all of the troll tribes, from the Echo Isles, through Zandalar, and to the deserts of Zul'farrak. Her followers are granted deadly poison to coat their weapons, and stealth to spy on their enemies undetected.

For many, the Loa of Spiders is considered a force of evil. But while she shows no mercy to her enemies, her cruelty never affects her allies - a trait that has cost Shadra dearly more than once already. Her own followers murdered her for her power during the Fourth War and her soul was sent to the Maw, to suffer in damnation.

Now, the Mistress of Spies has been reborn once more.]]
IMAGOdb.npcs.CAT_AMANI["shadra_midnight"].zones = {"Zul'Aman"}
IMAGOdb.npcs.CAT_AMANI["shadra_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_AMANI["shadra_midnight"].timeline = IMAGOdb.timelines.SHADRA

-- CAT_HARATI
IMAGOdb.npcs.CAT_HARATI["orweyna_midnight"].name = "Orweyna"
IMAGOdb.npcs.CAT_HARATI["orweyna_midnight"].aliases = {}
IMAGOdb.npcs.CAT_HARATI["orweyna_midnight"].race = "Haranir"
IMAGOdb.npcs.CAT_HARATI["orweyna_midnight"].lore =
[[
A scout of the mysterious race called Haranir, Orweyna is quite different from most of her kind. Fascinated with the world and its people outside of her homeland, she went against her oaths of secrecy and seclusion and made contact first with the champion of Azeroth in Azj-Kahet, and now with the elves of Quel'Thalas to petition their aid.
    
She has a special connection to her goddess, Aln'hara, receiving visions of impending dangers from her that resemble the Radiant Song, and she knows that the Void that threatens Aln'hara will require more than the forces of the Haranir to vanquish.]]
IMAGOdb.npcs.CAT_HARATI["orweyna_midnight"].zones = {"The Blinding Vale", "The Den", "Harandar", "Eversong Woods", "Isle of Quel'Danas", "Silvermoon City"}
IMAGOdb.npcs.CAT_HARATI["orweyna_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_HARATI["orweyna_midnight"].timeline = IMAGOdb.timelines.ORWEYNA

-- ELDER HAGAR --
IMAGOdb.npcs.CAT_HARATI["elder_hagar_midnight"].name = "Elder Hagar"

IMAGOdb.npcs.CAT_HARATI["elder_hagar_midnight"].aliases = {"Hagar"}
IMAGOdb.npcs.CAT_HARATI["elder_hagar_midnight"].race = "Haranir"
IMAGOdb.npcs.CAT_HARATI["elder_hagar_midnight"].lore = [[The haranir have many rules and traditions and as an Elder in the ruling council, it is Hagar's duty to enforce them. However, she does not agree with many of the old customs anymore.

Before she was an Elder, she was the Rootwarden of Teldrassil, tasked with the care of protecting the great World Tree. But what good are well-tended roots if the entire tree above ground is burned to ashes? Hagar could not stop her charge's decay and while she is still haunted by what has happened, she has also started to rethink what she thought true before. The haranir can not live isolated from the outside world forever and when Orweyna set out to make contact with Outsiders, Hagar was the only Elder to support her.]]
IMAGOdb.npcs.CAT_HARATI["elder_hagar_midnight"].zones = {"Silvermoon City", "Eversong Woods", "Harandar", "The Den"}
IMAGOdb.npcs.CAT_HARATI["elder_hagar_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_HARATI["elder_hagar_midnight"].timeline = IMAGOdb.timelines.ELDER_HAGAR

-- AMARAKK --
IMAGOdb.npcs.CAT_HARATI["amarakk_midnight"].name = "Amarakk"
IMAGOdb.npcs.CAT_HARATI["amarakk_midnight"].aliases = {}
IMAGOdb.npcs.CAT_HARATI["amarakk_midnight"].race = "Haranir"
IMAGOdb.npcs.CAT_HARATI["amarakk_midnight"].lore = [[When Amarakk was young, he still heard the song of the goddess. A good son from a good family, he preferred to go on adventures with his best friend Orweyna and didn't take life very seriously. When their adventures led them into the Rift of Aln though, Amarakk saw the madness and horror of what lurked under their very homes.

To choose the path of a Shul'ka is to forever cut oneself off from the song of the goddess - a mutilation of the mind for most haranir. Yet Amarakk knew this was his path, that he needed to go into the Rift again and fight, sacrificing his happiness for his people. Orweyna never understood that.]]
IMAGOdb.npcs.CAT_HARATI["amarakk_midnight"].zones = {"Isle of Quel'Danas", "Harandar", "The Dreamrift"}
IMAGOdb.npcs.CAT_HARATI["amarakk_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_HARATI["amarakk_midnight"].timeline = IMAGOdb.timelines.AMARAKK

-- ROOTWARDEN RUIA --
IMAGOdb.npcs.CAT_HARATI["rootwarden_ruia_midnight"].name = "Rootwarden Ruia"
IMAGOdb.npcs.CAT_HARATI["rootwarden_ruia_midnight"].race = "Haranir"
IMAGOdb.npcs.CAT_HARATI["rootwarden_ruia_midnight"].lore = [[As the Rootwarden of Shaladrassil, Ruia has seen the effects of the Lightbloom all too well when the infection spread from his world tree's roots into Harandar. With his village of Har'alnor in grave peril, he is thinking of taking desperate measures.

Always having been a bit standoffish, the Elder has now laid the blame for the blight of the Lightbloom on the elves' meddling with the Sunwell and strongly disapproves of working with the outsiders.]]
IMAGOdb.npcs.CAT_HARATI["rootwarden_ruia_midnight"].zones = {"The Blinding Vale", "Eversong Woods", "The Den", "Harandar"}
IMAGOdb.npcs.CAT_HARATI["rootwarden_ruia_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_HARATI["rootwarden_ruia_midnight"].timeline = IMAGOdb.timelines.ROOTWARDEN_RUIA

-- CAT_ARCANTINA

IMAGOdb.npcs.CAT_ARCANTINA["thisalee_crow_midnight"].name = "Thisalee Crow"
IMAGOdb.npcs.CAT_ARCANTINA["thisalee_crow_midnight"].race = "Night elf"
IMAGOdb.npcs.CAT_ARCANTINA["thisalee_crow_midnight"].lore = [[One of the younger night elven Druids of the Talon, Thisalee has fought for both nature and the Alliance through many of Azeroth's greatest conflicts. Patience has never been one of her virtues, and she tends to treat her superiors' orders as little more than suggestions. Her results speak for themselves, however, as her “kill first, ask questions later” attitude proved instrumental in saving the Wild God Aviana during the Cataclysm.

Despite her recklessness, Thisalee knows when she is out of her depth and can be counted on when it matters most.]]
IMAGOdb.npcs.CAT_ARCANTINA["thisalee_crow_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["thisalee_crow_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["thisalee_crow_midnight"].timeline = {
    {
        era = "Cata",
        text = [[Fought and slew the harpies on Mount Hyjal by the dozen against Skylord Omnuron's orders when she uncovered they were working with the black dragonflight. Found and safeguarded the egg of Aviana. Later overestimated her own abilities fighting the Firelands' elementals and regrouped with the other druids under Malfurion Stormrage during the invasion.]],
    },
    {
        era = "WoD",
        text = [[Fought under the Alliance commander against the Iron Horde in Gorgrond. Sent for reinforcements to take the fight to Warchief Grommash Hellscream.]],
    },
    {
        era = "Legion",
        text = [[Joined the druids in the Dreamgrove in the fight against the Burning Legion. Defended the Shrine of Aviana and saved Goldrinn. Helped the Archdruid slay the eredar commander Katith'rax after uncovering his plot to vanquish the Ancients.]],
    },
    {
        era = "BfA",
        text = [[Fought in the Battle of Darkshore and kept watch over the Twilight's Hammer, who sought to exploit the chaos of the Fourth War.]],
    },
    {
        era = "SL",
        text = [[Remained in Bashal'Aran until the Alliance's final victory against the Horde invaders in Darkshore.]],
    },
    {
        era = "DF",
        text = [[Joined the green dragonflight in their defense of the Ancient Bough from the Primalists' attacks. Moved to Bel'ameth after Amirdrassil bloomed.]],
    },
    {
        era = "TWW",
        text = [[Joined the Alliance army in the fight against Xal'atath on the Isle of Dorn.]],
    },
    {
        era = "Midnight",
        text = [[Shared a drink in the Arcantina with fellow druid Zen'tabra.]],
    }
}

-- GARONA HALFORCEN --
IMAGOdb.npcs.CAT_ARCANTINA["garona_halforcen_midnight"].name = "Garona Halforcen"
IMAGOdb.npcs.CAT_ARCANTINA["garona_halforcen_midnight"].aliases = {"Garona"}
IMAGOdb.npcs.CAT_ARCANTINA["garona_halforcen_midnight"].race = "Half-orc, half-draenei"
IMAGOdb.npcs.CAT_ARCANTINA["garona_halforcen_midnight"].lore = [[Garona will always be known for assassinating King Llane Wrynn of Stormwind and deciding the First War for the Old Horde. She mostly remembers it as being a near mindless puppet for Gul'dan and betraying the humans who had shown her more kindness than the ruthless Horde had all her life.  As her name implies, Garona was born to a draenei mother and an orc father and her heritage makes her an unusual individual. 

Her strained relationship with the Horde was mended over the years and she now serves her people once more as an assassin and spy, yet occasionally has worked with the Alliance when it served her goals.]]
IMAGOdb.npcs.CAT_ARCANTINA["garona_halforcen_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["garona_halforcen_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["garona_halforcen_midnight"].timeline = IMAGOdb.timelines.GARONA_HALFORCEN

-- ZEN TABRA --
IMAGOdb.npcs.CAT_ARCANTINA["zen_tabra_midnight"].name = "Zen'tabra"
IMAGOdb.npcs.CAT_ARCANTINA["zen_tabra_midnight"].race = "Troll"
IMAGOdb.npcs.CAT_ARCANTINA["zen_tabra_midnight"].lore = [[Zen'tabra was one of the first trolls of the Darkspear tribe to learn the art of druidism when the raptor loa Gonk contacted her through the Emerald Dream. With this newfound power, she helped keep the Echo Isles safe from enemies multiple times and negotiated entry for the Darkspear druids into the Cenarion Circle. 

After helping put a stop to Fyrakk's forces in the Emerald Dream during Amirdrassil's birth, Zen'tabra is now taking things a bit slower until the next threat to nature inevitably arrives.]]
IMAGOdb.npcs.CAT_ARCANTINA["zen_tabra_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["zen_tabra_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["zen_tabra_midnight"].timeline = IMAGOdb.timelines.ZEN_TABRA

-- REXXAR --
IMAGOdb.npcs.CAT_ARCANTINA["rexxar_midnight"].name = "Rexxar"

IMAGOdb.npcs.CAT_ARCANTINA["rexxar_midnight"].aliases = {}
IMAGOdb.npcs.CAT_ARCANTINA["rexxar_midnight"].race = "Half-Ogre, Half-Orc"
IMAGOdb.npcs.CAT_ARCANTINA["rexxar_midnight"].lore = [[Born as neither orc nor ogre, the Mok'Nathal hunter Rexxar, son of chieftain Leoroxx, has never cared much for the squabbles of others. He witnessed the descent of the Old Horde into fel-corrupted madness and pledged himself to Warchief Blackhand in order to have his clan spared. 

After the Second War was over, Rexxar abandoned the Horde. Cast out by his clan, feared by the Alliance and without any desire to rejoin his people, he began to live in Kalimdor's wilderness. Always by his side were his trusted animal companions, the bear Misha his closest friend among them. These beasts aren't pets or weapons to him, they are his family.

Rexxar has since somewhat rejoined the New Horde and society as a whole, but he will not be found staying in a city for long.]]
IMAGOdb.npcs.CAT_ARCANTINA["rexxar_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["rexxar_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["rexxar_midnight"].timeline = IMAGOdb.timelines.REXXAR

-- KELSEY STEELSPARK --
IMAGOdb.npcs.CAT_ARCANTINA["kelsey_steelspark_midnight"].name = "Kelsey Steelspark"
IMAGOdb.npcs.CAT_ARCANTINA["kelsey_steelspark_midnight"].race = "Gnome"
IMAGOdb.npcs.CAT_ARCANTINA["kelsey_steelspark_midnight"].lore = [[Agent Steelspark is the most prominent member of the Gnomeregan Covert Ops and an inventor by profession. Even though she owns a knife collection and is a member of the rogue order known as the Uncrowned, she isn't particularly proficient in hand-to-hand combat and prefers to use gadgets and explosives to take out her foes.]]
IMAGOdb.npcs.CAT_ARCANTINA["kelsey_steelspark_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["kelsey_steelspark_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["kelsey_steelspark_midnight"].timeline = IMAGOdb.timelines.KELSEY_STEELSPARK

-- GORGONNA --
IMAGOdb.npcs.CAT_ARCANTINA["gorgonna_midnight"].name = "Gorgonna"
IMAGOdb.npcs.CAT_ARCANTINA["gorgonna_midnight"].aliases = {}
IMAGOdb.npcs.CAT_ARCANTINA["gorgonna_midnight"].race = "Orc"
IMAGOdb.npcs.CAT_ARCANTINA["gorgonna_midnight"].lore = [[Gorgonna is the current chieftain of the Warsong Clan and values strength and honor in battle above all other virtues.

Loyal to the New Horde since being freed from the internment camps by Thrall, Gorgonna has learned from and internalized the mistakes of the Horde of old. After the fall of Garrosh Hellscream, she vowed to never lead the Warsong Clan down a similar dark path again.]]
IMAGOdb.npcs.CAT_ARCANTINA["gorgonna_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["gorgonna_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["gorgonna_midnight"].timeline = IMAGOdb.timelines.GORGONNA

-- LILLIAN VOSS --
IMAGOdb.npcs.CAT_ARCANTINA["lillian_voss_midnight"].name = "Lillian Voss"
IMAGOdb.npcs.CAT_ARCANTINA["lillian_voss_midnight"].race = "Undead"
IMAGOdb.npcs.CAT_ARCANTINA["lillian_voss_midnight"].lore = [[When she was alive, Lillian Voss was part of the Scarlet Crusade. Her enemies were the undead, and she made no distinction between Forsaken and Scourge. She hunted them, she hated them. And then she became one of them.

It took her a long time to accept what she had become and let go of her self-hatred. In the end, she found kinship among the ranks of the Forsaken of the Horde and brought solace to newly risen members by helping them accept their new unlife. 

She uses her considerable abilities for the sake of her people and is not above applying underhanded tactics. Even though she is so used to fighting, she now embraces the peace between the factions.]]
IMAGOdb.npcs.CAT_ARCANTINA["lillian_voss_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["lillian_voss_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["lillian_voss_midnight"].timeline = IMAGOdb.timelines.LILLIAN_VOSS

-- TEHD SHOEMAKER --
IMAGOdb.npcs.CAT_ARCANTINA["tehd_shoemaker_midnight"].name = "Tehd Shoemaker"
IMAGOdb.npcs.CAT_ARCANTINA["tehd_shoemaker_midnight"].aliases = {"Tehd"}
IMAGOdb.npcs.CAT_ARCANTINA["tehd_shoemaker_midnight"].race = "Undead Human"
IMAGOdb.npcs.CAT_ARCANTINA["tehd_shoemaker_midnight"].lore = [[Referred to as “Felbane's pet warlock” by Illidan Stormrage, this undead fel user has formed a very unlikely companionship with the demon hunter Marius Felbane. Despising each other for what they represent, the two men have begrudgingly accepted that they work together very efficiently. 

After defeating one hundred and fifty demons together since the third invasion of the Burning Legion, the two comrades have now set their sights on the Devouring Host.]]
IMAGOdb.npcs.CAT_ARCANTINA["tehd_shoemaker_midnight"].zones = {"Silvermoon City", "Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["tehd_shoemaker_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["tehd_shoemaker_midnight"].timeline = IMAGOdb.timelines.TEHD_SHOEMAKER

-- TAOSHI --
IMAGOdb.npcs.CAT_ARCANTINA["taoshi_midnight"].name = "Taoshi"
IMAGOdb.npcs.CAT_ARCANTINA["taoshi_midnight"].race = "Pandaren"
IMAGOdb.npcs.CAT_ARCANTINA["taoshi_midnight"].lore = [[The number two of the Shado-Pan, this roguish pandaren is one of the deadliest spies and assassins the land in the mists has to offer. Taoshi was front and center in defending Pandaria from the mantid, the sha, the Thunder King, and N'Zoth's forces. She rarely shies away from risky plans and sometimes it seems like a part of her lives for the danger her job tends to bring. The only person capable of reining her in is Shado-Pan leader Taran Zhu, to whom Taoshi is fiercely loyal.

Since Azeroth was threatened by the return of the Burning Legion, Taoshi helped to defend the world beyond her homeland as a high ranking member of the Uncrowned in Dalaran. Both Horde and Alliance can count on her assistance when needed, knowing full well that she has her allies' backs no matter what stands against them.]]
IMAGOdb.npcs.CAT_ARCANTINA["taoshi_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["taoshi_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["taoshi_midnight"].timeline = IMAGOdb.timelines.TAOSHI

-- VANESSA VANCLEEF --
IMAGOdb.npcs.CAT_ARCANTINA["vanessa_vancleef_midnight"].name = "Vanessa VanCleef"
IMAGOdb.npcs.CAT_ARCANTINA["vanessa_vancleef_midnight"].aliases = {"Vanessa"}
IMAGOdb.npcs.CAT_ARCANTINA["vanessa_vancleef_midnight"].race = "Human"
IMAGOdb.npcs.CAT_ARCANTINA["vanessa_vancleef_midnight"].lore = [[Vanessa VanCleef grew up on stories of Stormwind's horrific treatment of the Stonemasons and the greed of the noble class. Seeing her father Edwin murdered and decapitated by Alliance adventurers only hardened her beliefs. Under the guise of Hope Saldean, she became the leader of the Defias Brotherhood and sought vengeance by any means necessary.

Over the years, Vanessa has realized that war with Stormwind is not the solution to what truly matters to her: her home of Westfall. Still not trusting the crown, she left the Brotherhood and now aids the Breadbasket Guild to help the people of Westfall.]]
IMAGOdb.npcs.CAT_ARCANTINA["vanessa_vancleef_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["vanessa_vancleef_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["vanessa_vancleef_midnight"].timeline = IMAGOdb.timelines.VANESSA_VANCLEEF

--SCALECOMMANDER AZUREATHEL --
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_azurathel_midnight"].name = "Scalecommander Azurathel"
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_azurathel_midnight"].race = "Dracthyr"
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_azurathel_midnight"].lore = [[Azurathel was one of the first dracthyr created by Neltharion and was hand-picked by his maker to lead the Obsidian Warders – the shield on the front lines protecting the other dracthyr. After awakening from stasis during the rise of the Incarnates, he led his weyrn into the ranks of the Alliance. 

Even though he has vowed to keep Azeroth safe from danger, he has chosen to remember Neltharion with fondness, preferring to hold him in his memory as a father instead of the tyrant he became as Deathwing.]]
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_azurathel_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_azurathel_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_azurathel_midnight"].timeline = IMAGOdb.timelines.SCALECOMMANDER_AZURATHEL

-- CECILIA CLESSINGTON --
IMAGOdb.npcs.CAT_ARCANTINA["cecilia_clessington_midnight"].name = "Cecilia Clessington"
IMAGOdb.npcs.CAT_ARCANTINA["cecilia_clessington_midnight"].aliases = {"Cecilia"}
IMAGOdb.npcs.CAT_ARCANTINA["cecilia_clessington_midnight"].race = "Human"
IMAGOdb.npcs.CAT_ARCANTINA["cecilia_clessington_midnight"].lore = [[Cecilia Primrose Clessington the Second, only heir to Count Clessington of Stormwind's noble class. One would be mistaken to judge her the same as the other nobles of the kingdom though, as Cecilia has no interest in power, riches or influence. She sincerely wants to help the downtrodden and use her birthright to create a political voice for the farmers and workers of Westfall.

Together with Vanessa VanCleef, she has founded the Breadbasket Guild and developed a friendship with the former leader of the Defias.]]
IMAGOdb.npcs.CAT_ARCANTINA["cecilia_clessington_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["cecilia_clessington_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["cecilia_clessington_midnight"].timeline = IMAGOdb.timelines.CECILIA_CLESSINGTON

-- MARIUS FELBANE --
IMAGOdb.npcs.CAT_ARCANTINA["marius_felbane_midnight"].name = "Marius Felbane"
IMAGOdb.npcs.CAT_ARCANTINA["marius_felbane_midnight"].race = "Night Elf"
IMAGOdb.npcs.CAT_ARCANTINA["marius_felbane_midnight"].lore = [[Demon hunter Marius Felbane harbors a hatred for the Burning Legion rivaled by few others. His abhorrence runs deep enough that he was willing to team up with the warlock Tehd Shoemaker, despite despising what his undead companion represents. He barely saw him as a person at first but had to begrudgingly admit that they fight exceptionally well together. 

After slaying over one hundred and fifty demons since the Legion's invasion of the Broken Shore, the two have now set their sights on new enemies.]]
IMAGOdb.npcs.CAT_ARCANTINA["marius_felbane_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["marius_felbane_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["marius_felbane_midnight"].timeline = IMAGOdb.timelines.MARIUS_FELBANE

-- FLYNN FAIRWIND --
IMAGOdb.npcs.CAT_ARCANTINA["flynn_fairwind_midnight"].name = "Flynn Fairwind"
IMAGOdb.npcs.CAT_ARCANTINA["flynn_fairwind_midnight"].aliases = {"Flynn"}
IMAGOdb.npcs.CAT_ARCANTINA["flynn_fairwind_midnight"].race = "Human"
IMAGOdb.npcs.CAT_ARCANTINA["flynn_fairwind_midnight"].lore = [[The dashing swashbuckler Captain Flynn Fairwind is seldom found without a drink in his hand and a quip on his lips. Forced into piracy from an early age, his street-smarts and charm quickly made him a recognized name on the seas of Kul Tiras. Even though he was living a life of crime, he never could let go entirely of his inherent sense of justice. 

Now, he works for the Kul Tiran admiralty both as captain of two ships and as an expert for some of the more stealthy jobs that require more creative solutions. When the Fourth War broke out, he undertook various missions with the Alliance's own spies, the SI:7. He met Stormwind's spymaster Mathias Shaw and the two eventually fell in love – after a somewhat relentless pursuit from Flynn. 

With the war over, Flynn now enjoys a calmer life, living in Stormwind City and going on the occasional adventure. His aid to Alliance is greatly appreciated, despite the habitual smuggling now and then.]]
IMAGOdb.npcs.CAT_ARCANTINA["flynn_fairwind_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["flynn_fairwind_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["flynn_fairwind_midnight"].timeline = IMAGOdb.timelines.FLYNN_FAIRWIND

-- SCALECOMMANDER EMBERTHAL --
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_emberthal_midnight"].name = "Scalecommander Emberthal"
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_emberthal_midnight"].race = "Dracthyr"
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_emberthal_midnight"].lore = [[Emberthal is the leader of the Ebon Scales, the weyrn of dracthyr empowered with the magics of the black dragonflight. Like her fellow soldiers she was created by Neltharion before he gave in to corruption, and even after being imprisoned by him for thousands of years, she couldn't help but feel sadness and confusion at her father's fate. 

Unlike her former friend Sarkareth, Emberthal rejected Deathwing's legacy and has united the dracthyr in harmony and a desire for peace on Azeroth.]]
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_emberthal_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_emberthal_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["scalecommander_emberthal_midnight"].timeline = IMAGOdb.timelines.SCALECOMMANDER_EMBERTHAL

-- WRATHION --
IMAGOdb.npcs.CAT_ARCANTINA["wrathion_midnight"].name = "Wrathion"
IMAGOdb.npcs.CAT_ARCANTINA["wrathion_midnight"].race = "Black Dragon"
IMAGOdb.npcs.CAT_ARCANTINA["wrathion_midnight"].lore = [[Son of Deathwing, heir to a corrupted dragonflight – Wrathion had heard of his evil heritage before he had even hatched from his egg. Born without the taint of the Old Gods, the young dragon made a conscious effort to protect Azeroth from malign forces rather than seek her destruction like the rest of his dragonflight.

His ambitious plans included setting the Alliance up for total victory over the Horde to unite the world against the Burning Legion, allying with the infinite dragonflight to create armies in other dimensions, and creating a network of spies to systematically take out corrupted black dragons. He regrets many of the actions of his past, now that he has matured, and has since managed to save the world from the Old God, N'Zoth, and united with the other dragons against the Primal Incarnates. Most Azerothians now see him as an ally and hero, but his past and Deathwing's legacy are still haunting him.

Being hunted since he was a whelpling, Wrathion didn't have friends or family to rely on, and a part of him will never shake the feeling of being alone and unworthy of love. He betrayed the only friend he ever had – Anduin Wrynn – and his draconic kin lay dead. On the Dragon Isles he finally found a place of acceptance and peace. He forged bonds with his older brothers and helped lead his reformed flight back into Azeroth's service.]]
IMAGOdb.npcs.CAT_ARCANTINA["wrathion_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["wrathion_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["wrathion_midnight"].timeline = IMAGOdb.timelines.WRATHION

-- TRAVARD --
IMAGOdb.npcs.CAT_ARCANTINA["travard_midnight"].name = "Travard"
IMAGOdb.npcs.CAT_ARCANTINA["travard_midnight"].race = "Human"
IMAGOdb.npcs.CAT_ARCANTINA["travard_midnight"].lore = [[Travard is an old paladin and the last survivor of the original Tyr's Guard – an order dedicated to defending the fallen titan keeper, Tyr, after his sacrifice against the Old Gods. 

Since the rise of the Primalists, he has reestablished the Tyr's Guard, recruiting new members on the Dragon Isles. Working with the bronze and the infinite dragonflight, Travard and his group of paladins managed to restore Tyr back to life.

Their mission now is to guide their hero in this new world and help him find his place as her protector once more.]]
IMAGOdb.npcs.CAT_ARCANTINA["travard_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["travard_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["travard_midnight"].timeline = IMAGOdb.timelines.TRAVARD

-- NISHA --
IMAGOdb.npcs.CAT_ARCANTINA["nisha_midnight"].name = "Nisha"
IMAGOdb.npcs.CAT_ARCANTINA["nisha_midnight"].race = "Vulpera"
IMAGOdb.npcs.CAT_ARCANTINA["nisha_midnight"].lore = [[The 'Fury of the Vulpera' has always been the shield other vulpera could hide behind when their caravans were still roaming the desert of Vol'dun. Unlike her reserved leader and friend, Kiro, Nisha prefers to use offense as the best defense when dealing with her enemies. It goes without saying that she was enthusiastic to join the Horde.

After the end of the Fourth War, Nisha now spends her time exploring the world, brawling, drinking, making new friends, and generally living her best life.]]
IMAGOdb.npcs.CAT_ARCANTINA["nisha_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["nisha_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["nisha_midnight"].timeline = IMAGOdb.timelines.NISHA

-- CYRUS CRESTFALL --
IMAGOdb.npcs.CAT_ARCANTINA["cyrus_crestfall_midnight"].name = "Cyrus Crestfall"
IMAGOdb.npcs.CAT_ARCANTINA["cyrus_crestfall_midnight"].race = "Human"
IMAGOdb.npcs.CAT_ARCANTINA["cyrus_crestfall_midnight"].lore = [[This man is a true patriot of Kul Tiras and a veteran of the Second War. He fought loyally under Daelin Proudmoore and, when asked, will readily share lengthy tales about every battle he braved. While he is still saddened by the loss of all the friends and comrades who fell against the Horde, he still longs for the fight and was taken aback when his Lord Admiral ordered him to stay behind during the assault on Theramore to care for a little girl. As always, however, he followed his lord's orders.

His young charge grew up to become a valiant paladin named Taelia Fordragon, and he couldn't be prouder of who she has become under his tutelage. Because of her, he no longer regrets having been forced to take on a desk job and proudly continues serving Kul Tiras as the harbormaster of Boralus. He played a key role in Kul Tiras's re-entry into the Alliance, and although he no longer expects to fight for his nation, his sword still feels right in his hand should he ever need to draw it again.]]
IMAGOdb.npcs.CAT_ARCANTINA["cyrus_crestfall_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["cyrus_crestfall_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["cyrus_crestfall_midnight"].timeline = IMAGOdb.timelines.CYRUS_CRESTFALL

IMAGOdb.npcs.CAT_ARCANTINA["misha_midnight"].name = "Misha"
IMAGOdb.npcs.CAT_ARCANTINA["misha_midnight"].race = "Bear"
IMAGOdb.npcs.CAT_ARCANTINA["misha_midnight"].lore = [[Never far from Rexxar's side is his loyal friend and companion, Misha. She was orphaned as a little cub in Feralas and found by the wandering Mok'Nathal by chance. Both were alone and without family or kin, and quickly became inseparable. 

It would be unwise to mistake her cuddly appearance for harmlessness. Get on Rexxar's bad side, and if the hunter doesn't end you, Misha certainly will.]]
IMAGOdb.npcs.CAT_ARCANTINA["misha_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["misha_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["misha_midnight"].timeline = IMAGOdb.timelines.MISHA

-- LORD DARIUS CROWLEY --
IMAGOdb.npcs.CAT_ARCANTINA["lord_darius_crowley_midnight"].name = "Lord Darius Crowley"
IMAGOdb.npcs.CAT_ARCANTINA["lord_darius_crowley_midnight"].race = "Worgen"
IMAGOdb.npcs.CAT_ARCANTINA["lord_darius_crowley_midnight"].lore = [[A proud and selfless Gilnean nobleman and once the closest friend of King Genn Greymane. Darius was branded a traitor to his homeland shortly after the Third War, when he incited a rebellion against his king in protest of the isolationist course Genn had set for the nation. Never losing his idealism, Crowley fought for Gilneas without hesitation once more when the worgen curse and Forsaken takeover sealed the declining kingdom's fate. He even gave up his humanity for the cause.

Now, with Gilneas liberated and at peace, Darius can finally take a moment to rest and take pride in seeing his daughter grow up in the world they both fought for.]]
IMAGOdb.npcs.CAT_ARCANTINA["lord_darius_crowley_midnight"].zones = {"Arcantina"}
IMAGOdb.npcs.CAT_ARCANTINA["lord_darius_crowley_midnight"].source = "Cadash"
IMAGOdb.npcs.CAT_ARCANTINA["lord_darius_crowley_midnight"].timeline = IMAGOdb.timelines.LORD_DARIUS_CROWLEY